"""A Level Economics (0725), Upper Sixth: National Income Accounting & Keynesian Equilibrium,
Money, Banking & Monetary Policy, Public Finance & Fiscal Policy.

All national figures in examples are invented for practice unless stated otherwise.
"""

from .dsl import *  # noqa: F403

COURSE = ("economics", "upper-sixth")

M1 = "National Income Accounting & Keynesian Equilibrium"
M2 = "Money, Banking & Monetary Policy"
M3 = "Public Finance & Fiscal Policy"

LESSONS = [
    # ================================================================ 1. National income accounting
    lesson(
        module=M1, topic="National income accounting",
        title="National income accounting: GDP, GNP, NNP and real output",
        slug="ecu1-national-income-accounting",
        minutes=24,
        summary="The three ways of measuring national output, the move from GDP to GNP, NNP and national income at factor cost, value added, and real GDP with the GDP deflator.",
        objectives=[
            "Explain why output, income and expenditure measures give the same total",
            "Move from GDP at market prices to GNP, NNP and national income at factor cost",
            "Use value added to avoid double counting",
            "Convert nominal GDP to real GDP with the GDP deflator and judge what the figures show",
        ],
        key_concepts=["Gross domestic product", "Gross national product", "Net property income from abroad",
                      "Depreciation (capital consumption)", "Market prices and factor cost", "Value added",
                      "Transfer payments", "GDP deflator", "Real and nominal GDP"],
        blocks=[
            H("Introduction"),
            T("When the government of Cameroon presents its Finance Law, or when the IMF writes about the CEMAC economies, the first number quoted is usually the growth of **GDP**. "
              "Behind that number sits a large accounting exercise: adding up what millions of farmers, traders, firms and public bodies produce in a year without counting anything twice.\n\n"
              "At O Level you learnt the three methods in outline. At A Level you must move confidently between the different aggregates (GDP, GNP, NNP, at market prices or at factor cost), "
              "and separate changes in **real** output from changes caused only by prices."),
            H("Three measures of one flow"),
            D("**National income accounting** is the system of accounts that measures the total value of goods and services produced in an economy over a period, usually a year, and the incomes and spending that go with it.", title="Definition"),
            KEY("Output = income = expenditure", "Every franc spent on final output is received by someone as income, and it is the value of something produced. So, apart from measurement errors, the three methods give the same total.", cards=[
                ["Output method", "Add the value added by each industry (agriculture, mining, manufacturing, services)."],
                ["Income method", "Add factor incomes: wages, rent, interest and profits. Leave out transfer payments."],
                ["Expenditure method", "Add spending on final output: C + I + G + (X - M)."]],
                note="In practice the totals differ slightly; statisticians show a 'statistical discrepancy' to balance them."),
            D("**Value added** is the value of a firm's output minus the value of the inputs it bought from other firms. Adding value added at every stage gives the value of final output and avoids **double counting**.", title="Definition"),
            D("**Transfer payments** are payments for which no good or service is produced in return, such as pensions, scholarships and gifts. They move income from one person to another, so they are left out of the income method.", title="Definition"),
            EX("Worked example 1: value added in the cocoa chain", intro="A farmer near Kumba sells cocoa beans for FCFA 200 (thousand). A processor turns them into paste and sells it for 500. A chocolate maker sells the chocolate to consumers for 900. Find the contribution to GDP. (Figures invented for practice.)", steps=[
                S("Value added by the farmer", math=r"200 - 0 = 200", text="We assume the farmer bought no inputs."),
                S("Value added by the processor", math=r"500 - 200 = 300"),
                S("Value added by the chocolate maker", math=r"900 - 500 = 400"),
                S("Total value added", math=r"200 + 300 + 400 = 900", text="This equals the price of the final product. Adding 200 + 500 + 900 = 1 600 would count the beans three times."),
            ], check=r"200 + 300 + 400 = 900"),
            H("From GDP to national income"),
            D("**Gross domestic product (GDP)** is the value of all final output produced inside a country's borders in a year, whoever owns the factors. **Gross national product (GNP)**, also called gross national income, is the output produced by factors owned by the country's residents, wherever they work.", title="Definition"),
            F(r"\begin{aligned} \text{GNP} &= \text{GDP} + \text{net property income from abroad} \\ \text{NNP} &= \text{GNP} - \text{depreciation} \\ \text{Factor cost} &= \text{market prices} - \text{indirect taxes} + \text{subsidies} \end{aligned}", title="From GDP to national income"),
            T("**Net property income from abroad** is income earned abroad by residents (wages, interest, profits, dividends) minus income earned at home by foreigners. For many developing countries with large foreign-owned mines, oil fields and plantations it is negative, so GNP is less than GDP.\n\n"
              "**Depreciation** (capital consumption) is the value of capital worn out during the year; net figures show what is left after replacing it.\n\n"
              "Market prices include indirect taxes such as VAT and are lowered by subsidies. Factor cost shows what the factors of production actually received. **National income** in the narrow sense is NNP at factor cost."),
            EX("Worked example 2: from GDP to national income", intro="Data for a country (billion FCFA, invented for practice): consumption 6 000, investment 1 500, government spending 1 200, exports 2 000, imports 2 200, net property income from abroad -300, depreciation 700, indirect taxes 900, subsidies 100. Find GDP and GNP at market prices, NNP at market prices and national income (NNP at factor cost).", steps=[
                S("GDP at market prices", math=r"6\,000 + 1\,500 + 1\,200 + 2\,000 - 2\,200 = 8\,500"),
                S("GNP at market prices", math=r"8\,500 + (-300) = 8\,200"),
                S("NNP at market prices", math=r"8\,200 - 700 = 7\,500"),
                S("National income (NNP at factor cost)", math=r"7\,500 - 900 + 100 = 6\,700"),
            ], check=r"8\,500 - 300 - 700 - 900 + 100 = 6\,700"),
            H("Real and nominal GDP"),
            D("**Nominal GDP** is valued at the prices of the year itself (current prices). **Real GDP** is valued at the prices of a base year (constant prices), so it changes only when the volume of output changes.", title="Definition"),
            F(r"\text{GDP deflator} = \frac{\text{nominal GDP}}{\text{real GDP}} \times 100 \qquad \text{Real GDP} = \frac{\text{nominal GDP}}{\text{GDP deflator}} \times 100", title="GDP deflator and real GDP"),
            EX("Worked example 3: real growth", intro="Nominal GDP was 10 000 in year 1 (the base year) and 11 550 in year 2. The GDP deflator in year 2 is 105. Find real GDP in year 2 and the real growth rate.", steps=[
                S("Real GDP in year 2", math=r"\frac{11\,550}{105} \times 100 = 11\,000"),
                S("Real growth rate", math=r"\frac{11\,000 - 10\,000}{10\,000} \times 100 = 10\%"),
                S("Compare with nominal growth", math=r"\frac{11\,550 - 10\,000}{10\,000} \times 100 = 15.5\%", text="Part of the 15.5% rise was only higher prices; the volume of output rose by 10%."),
            ]),
            H("Uses and limits of the figures"),
            KEY("Evaluation: what national income figures miss", "Examiners reward candidates who can judge the figures, not only calculate them.", cards=[
                ["The informal sector", "Much of the output of small traders, farmers and artisans is not recorded, so GDP is underestimated (estimates must be used)."],
                ["Subsistence output", "Food grown and eaten by the family is not sold, so it has to be imputed or is missed."],
                ["Distribution", "GDP per head is an average; it says nothing about how income is shared."],
                ["Quality of life", "Leisure, pollution, depletion of forests and oil, and unpaid housework are left out."],
                ["GDP versus GNP", "Where much profit is sent abroad, GNP is a better guide to residents' income than GDP."]]),
            MISTAKE("Adding transfer payments in the income method", "Pensions and scholarships are not payments for current output. Count only wages, rent, interest and profit (and mixed incomes of the self-employed)."),
            MISTAKE("Getting the factor cost adjustment the wrong way round", "To go from market prices to factor cost you SUBTRACT indirect taxes and ADD subsidies. Going the other way, you add taxes and subtract subsidies."),
            QUIZ("A country's GDP at market prices is 900, net property income from abroad is -60, depreciation is 80. What is NNP at market prices?",
                 ["760", "880", "1 040", "920"], 0,
                 "GNP = 900 - 60 = 840, then NNP = 840 - 80 = 760.",
                 hint="Go GDP to GNP first, then gross to net.",
                 feedback=["", "This subtracts depreciation but adds the net property income instead of subtracting it.", "This adds both items instead of subtracting.", "This ignores depreciation and adds the property income."]),
            QUIZ("Nominal GDP rises by 8% in a year in which the GDP deflator rises by 8%. What happened to real GDP?",
                 ["It rose by 8%", "It rose by 16%", "It stayed about the same", "It fell by 8%"], 2,
                 "All of the rise in value came from higher prices, so the volume of output was about unchanged.",
                 hint="Real GDP = nominal GDP divided by the price index.",
                 feedback=["That is the nominal change, which includes prices.", "You added the price rise instead of removing it.", "", "Real output fell only if prices rose faster than nominal GDP."]),
            TIP("National income accounting appears in Paper 1 as calculations (aggregates, deflator, value added) and in Paper 2 and Paper 3 as definitions and data. The Board's 2023 report notes that many candidates avoid national income questions; learning the chain GDP to GNP to NNP to factor cost removes that fear.", title="Exam link"),
            PQ("Given: GNP at market prices 5 400, net property income from abroad 200, indirect taxes 600, subsidies 50, depreciation 450. Find GDP at market prices and national income at factor cost.",
               "GDP = GNP - net property income = 5 400 - 200 = 5 200. NNP at market prices = 5 400 - 450 = 4 950. National income = 4 950 - 600 + 50 = 4 400."),
            PQ("Nominal GDP is 12 000 in the base year and 13 200 a year later; the GDP deflator is 110. Find real GDP and comment on growth.",
               "Real GDP = 13 200 / 110 x 100 = 12 000. Real GDP did not change: the 10% rise in nominal GDP was entirely due to prices."),
            PQ("Explain three reasons why the GDP per head of a developing country may give a poor picture of its standard of living.",
               "Plan: (1) the informal and subsistence sectors are under-recorded, so true output may be higher; (2) GDP per head is an average and hides inequality between regions and groups; (3) it leaves out quality-of-life factors such as health, education, pollution and leisure; also, prices differ between countries, so exchange-rate comparisons mislead (purchasing power). Evaluate: GDP is still the most widely available measure, so it is used together with other indicators such as the HDI."),
            PQ("Why is GNP smaller than GDP in many economies with large foreign-owned mining or oil firms?",
               "Profits and interest earned by foreign owners are sent abroad. Net property income from abroad is therefore negative, and GNP = GDP + (negative amount) is smaller than GDP."),
            SUM("Output, income and expenditure measure the same flow; value added avoids double counting and transfer payments are left out.",
                "GNP = GDP + net property income from abroad; NNP = GNP - depreciation.",
                "Factor cost = market prices - indirect taxes + subsidies; national income is NNP at factor cost.",
                "Real GDP = nominal GDP / deflator x 100; growth means a rise in real GDP.",
                "The figures miss informal and subsistence output, distribution and quality of life."),
        ],
    ),
    # ================================================================ 2. Circular flow and aggregate expenditure
    lesson(
        module=M1, topic="The circular flow and aggregate expenditure",
        title="The circular flow, aggregate expenditure and Keynesian equilibrium",
        slug="ecu1-circular-flow-aggregate-expenditure",
        minutes=25,
        summary="Two-, three- and four-sector circular flows, leakages and injections, total final expenditure versus aggregate expenditure, and how equilibrium income is found with AE = Y and W = J.",
        objectives=[
            "Describe the two-, three- and four-sector circular flow with its leakages and injections",
            "Distinguish total final expenditure from aggregate expenditure",
            "Find equilibrium national income with AE = Y and with W = J",
            "Explain how unplanned changes in stocks move the economy towards equilibrium",
        ],
        key_concepts=["Circular flow of income", "Leakage (withdrawal)", "Injection", "Total final expenditure",
                      "Aggregate expenditure", "Planned and actual spending", "Equilibrium national income", "Keynesian cross"],
        blocks=[
            H("Introduction"),
            T("John Maynard Keynes argued in the 1930s that the level of output and employment depends on total spending. If people and firms plan to spend less than the economy produces, unsold goods pile up and firms cut output and jobs. "
              "This lesson builds the model he used: the circular flow and the **income-expenditure model**, often drawn as the **Keynesian cross**."),
            H("The circular flow in stages"),
            T("**Two sectors** (households and firms). Firms pay factor incomes to households; households spend on firms' goods. The only leakage is **saving (S)** and the only injection is **investment (I)**.\n\n"
              "**Three sectors** add the government: **taxes (T)** are a leakage and **government spending (G)** an injection. **Four sectors** add the rest of the world: **imports (M)** are a leakage and **exports (X)** an injection."),
            IMG("alecu1-circular-flow4.svg", alt="Circular flow: households pay consumer spending to firms and receive factor incomes. Taxes go from households to government, saving to the financial sector, imports to the rest of the world. Government spending, investment and exports flow into firms.", caption="Figure 1. The four-sector circular flow. Leakages (brown) leave the flow; injections (green) enter it."),
            D("A **leakage** (withdrawal) is income that is not passed on in the circular flow through spending on domestic output: S, T and M. An **injection** is spending on domestic output that does not come from households' consumption: I, G and X.", title="Definition"),
            KEY("Why injections and leakages differ", "Injections are decided mainly by people other than those who make the leakages.", cards=[
                ["Saving", "Households, depending mostly on income."],
                ["Investment", "Firms, depending on expected profit and interest rates."],
                ["Taxes and spending", "Government budget decisions."],
                ["Imports and exports", "Domestic incomes decide imports; foreign incomes and prices decide exports."]]),
            H("Total final expenditure and aggregate expenditure"),
            D("**Total final expenditure (TFE)** is all spending on final goods and services: TFE = C + I + G + X. It includes spending on imported goods. **Aggregate expenditure (AE)**, or aggregate demand at each income level, is spending on DOMESTIC output: AE = C + I + G + (X - M).", title="Definition"),
            EX("Worked example 1: TFE and AE", intro="Consumption 6 000, investment 1 500, government spending 1 200, exports 2 000, imports 2 200 (billion FCFA, invented). Find TFE and aggregate expenditure.", steps=[
                S("TFE", math=r"6\,000 + 1\,500 + 1\,200 + 2\,000 = 10\,700"),
                S("Subtract imports", math=r"10\,700 - 2\,200 = 8\,500", text="This is aggregate expenditure on domestic output, equal to GDP at market prices."),
            ]),
            H("Equilibrium national income"),
            D("**Equilibrium national income** is the level of income at which planned aggregate expenditure equals output (AE = Y). Then firms sell exactly what they produce and have no reason to change output. Equivalently, planned leakages equal planned injections (W = J).", title="Definition"),
            F(r"Y = C + I + G + (X - M) \quad\Longleftrightarrow\quad S + T + M = I + G + X", title="Two equivalent conditions"),
            IMG("alecu1-keynesian-cross.svg", alt="Keynesian cross: aggregate expenditure on the vertical axis, national income on the horizontal. A 45-degree line AE = Y and a flatter AE line starting at A on the vertical axis cross at E above income Ye.", caption="Figure 2. The Keynesian cross. Every point on the 45-degree line has AE = Y; equilibrium is where the AE line crosses it."),
            T("The AE line is flatter than the 45-degree line because only part of each extra franc of income is spent on domestic output (the rest is saved, taxed or spent on imports). Its intercept A is **autonomous spending**, the spending that does not depend on income."),
            EX("Worked example 2: a two-sector economy", intro="C = 100 + 0.8Y and planned investment I = 200. Find equilibrium income and check that S = I.", steps=[
                S("Set Y = AE", math=r"Y = 100 + 0.8Y + 200"),
                S("Collect terms", math=r"0.2Y = 300"),
                S("Solve", math=r"Y = 1\,500"),
                S("Check with leakages", math=r"S = Y - C = -100 + 0.2Y = -100 + 300 = 200 = I"),
            ], check=r"100 + 0.8(1\,500) + 200 = 1\,500"),
            EX("Worked example 3: a four-sector economy", intro="C = 50 + 0.75Yd, where disposable income Yd = Y - T and T = 0.2Y. I = 150, G = 200, X = 120, M = 0.1Y. Find equilibrium income and check W = J.", steps=[
                S("Disposable income", math=r"Y_d = Y - 0.2Y = 0.8Y"),
                S("Consumption in terms of Y", math=r"C = 50 + 0.75(0.8Y) = 50 + 0.6Y"),
                S("AE", math=r"AE = 50 + 0.6Y + 150 + 200 + 120 - 0.1Y = 520 + 0.5Y"),
                S("Set Y = AE", math=r"Y = 520 + 0.5Y \Rightarrow 0.5Y = 520 \Rightarrow Y = 1\,040"),
                S("Check W = J", math=r"S + T + M = 158 + 208 + 104 = 470 = 150 + 200 + 120", text="S = Yd - C = 832 - 674 = 158; T = 0.2 x 1 040 = 208; M = 0.1 x 1 040 = 104."),
            ]),
            H("How the economy gets there"),
            T("Suppose in Worked example 2 firms produce Y = 1 800. Planned spending is 100 + 0.8(1 800) + 200 = 1 740. Firms sell 60 less than they make, so stocks rise by 60 without being planned. They cut output, and income falls towards 1 500. "
              "Below 1 500 the reverse happens: stocks run down and firms expand. In the national accounts, **actual** saving always equals **actual** investment, because unplanned stock changes are counted as investment; equilibrium needs **planned** values to be equal."),
            KEY("Evaluation of the Keynesian model", "", cards=[
                ["Strength", "Explains why an economy can stay at an equilibrium with unemployment; gives a basis for active fiscal policy."],
                ["Limit: prices", "The simple model holds prices constant; it fits an economy with spare capacity better than one at full employment."],
                ["Limit: behaviour", "Consumption and investment functions change with confidence, credit and interest rates."],
                ["Limit: developing economies", "Supply bottlenecks, a large informal sector and imports can weaken the link from spending to domestic output."]]),
            MISTAKE("Including net exports in TFE", "TFE = C + I + G + X. Imports are subtracted only to get spending on domestic output (AE or GDP). The Board's 2023 report noted candidates confusing the two."),
            MISTAKE("Saying 'S = I' always means equilibrium", "Actual S always equals actual I by accounting. Equilibrium needs PLANNED leakages to equal PLANNED injections."),
            QUIZ("In a three-sector closed economy, which pair consists only of injections?",
                 ["Saving and taxes", "Investment and government spending", "Imports and exports", "Consumption and investment"], 1,
                 "Investment and government spending add to demand for output from outside household consumption.",
                 hint="Injections add spending that does not come from households' consumption.",
                 feedback=["Both are leakages.", "", "There is no foreign trade in a closed economy; and imports are a leakage.", "Consumption is part of the inner flow, not an injection."]),
            QUIZ("At the current output, planned leakages are greater than planned injections. What happens next?",
                 ["Stocks fall and output rises", "Output stays the same", "Unplanned stocks build up and output falls", "Prices must rise"], 2,
                 "More is withdrawn than injected, so planned spending is less than output; unsold goods pile up and firms cut production.",
                 hint="Compare planned spending with what firms produce.",
                 feedback=["That happens when injections exceed leakages.", "Output stays the same only when W = J.", "", "In the simple model firms react through output, not prices."]),
            TIP("In Paper 2 and Paper 3, draw the Keynesian cross or the W = J diagram and label both axes, the 45-degree line and the equilibrium. In Paper 1, expect quick equilibrium calculations.", title="Exam link"),
            PQ("C = 80 + 0.75Y and I = 120 in a two-sector economy. Find equilibrium income, consumption and saving.",
               "Y = 80 + 0.75Y + 120, so 0.25Y = 200 and Y = 800. C = 80 + 600 = 680. S = 800 - 680 = 120 = I."),
            PQ("Using the economy in Worked example 3, explain what happens if output is 1 200.",
               "AE = 520 + 0.5(1 200) = 1 120 < 1 200. Firms sell 80 less than they produce; unplanned stocks rise; they cut output and incomes until Y = 1 040."),
            PQ("Distinguish between total final expenditure and aggregate expenditure, and explain why the difference matters for Cameroon.",
               "TFE = C + I + G + X is all spending on final output, including spending that goes on imported goods. AE = C + I + G + (X - M) is spending on domestic output only. For an economy that imports much of its manufactured and capital goods, a large part of TFE leaks abroad, so a rise in spending may raise domestic income much less than TFE suggests."),
            PQ("Explain, with a diagram, how equilibrium national income is determined in the income-expenditure model.",
               "Plan: draw AE (vertical) against Y (horizontal), the 45-degree line and an AE line with a positive intercept and slope less than 1; equilibrium where they cross. Explain: above equilibrium AE < Y, stocks rise, output falls; below it AE > Y, stocks fall, output rises. State W = J as the same condition. Evaluate: the equilibrium need not be at full employment, which is the key Keynesian conclusion; the model assumes fixed prices and spare capacity."),
            SUM("Leakages are S, T and M; injections are I, G and X.",
                "TFE = C + I + G + X; AE = C + I + G + (X - M) is spending on domestic output.",
                "Equilibrium: planned AE = Y, or planned W = planned J.",
                "Unplanned stock changes push output towards equilibrium.",
                "Equilibrium may be below full employment; the model assumes spare capacity and fixed prices."),
        ],
    ),
    # ================================================================ 3. Consumption, saving and investment
    lesson(
        module=M1, topic="Consumption, saving and investment",
        title="Consumption and saving functions, and the determinants of investment",
        slug="ecu1-consumption-saving-investment",
        minutes=25,
        summary="The Keynesian consumption and saving functions, APC, APS, MPC and MPS, what else shifts consumption and saving, autonomous and induced investment, and the marginal efficiency of capital.",
        objectives=[
            "Write and interpret the consumption function C = a + bY and the saving function",
            "Calculate APC, APS, MPC and MPS and use APC + APS = 1 and MPC + MPS = 1",
            "Explain the determinants of consumption, saving and investment in a directional way",
            "Use the marginal efficiency of capital to decide whether an investment is worthwhile",
        ],
        key_concepts=["Consumption function", "Autonomous consumption", "Marginal propensity to consume",
                      "Average propensity to consume", "Saving function", "Autonomous and induced investment",
                      "Marginal efficiency of capital", "Break-even income"],
        blocks=[
            H("Introduction"),
            T("When a civil servant in Bamenda gets a pay rise, she will probably spend most of it and save a little, perhaps in a njangi or a bank account. Keynes built his model on this observation, which he called a 'psychological law': "
              "as income rises, consumption rises, but by less than the rise in income. Consumption is the largest part of aggregate expenditure; investment is smaller but much more unstable."),
            H("The consumption function"),
            D("The **consumption function** shows planned consumption at each level of (disposable) income. In its simplest linear form C = a + bY, where **a** is **autonomous consumption** (spending even at zero income, financed by past saving or borrowing) and **b** is the **marginal propensity to consume (MPC)**.", title="Definition"),
            F(r"\text{MPC} = \frac{\Delta C}{\Delta Y} \qquad \text{APC} = \frac{C}{Y}", title="Marginal and average propensities to consume"),
            F(r"S = Y - C = -a + (1 - b)Y \qquad \text{MPS} = \frac{\Delta S}{\Delta Y} = 1 - \text{MPC}", title="The saving function"),
            F(r"\text{APC} + \text{APS} = 1 \qquad \text{MPC} + \text{MPS} = 1", title="Two identities (no taxes)"),
            IMG("alecu1-consumption.svg", alt="Consumption function: a straight line starting at a on the vertical axis, flatter than the 45-degree line, crossing it at the break-even point B above income Y1. To the left the vertical gap is dissaving, to the right it is saving.", caption="Figure 1. The consumption function. At B consumption equals income and saving is zero."),
            EX("Worked example 1: a consumption schedule", intro="C = 40 + 0.75Y (billion FCFA, invented). Find C, S, APC and APS at Y = 80, 160 and 400, and the break-even income.", steps=[
                S("Y = 80", math=r"C = 40 + 60 = 100,\; S = -20,\; \text{APC} = 1.25", text="Dissaving: people spend more than their income."),
                S("Y = 160", math=r"C = 40 + 120 = 160,\; S = 0,\; \text{APC} = 1", text="This is break-even income."),
                S("Y = 400", math=r"C = 40 + 300 = 340,\; S = 60,\; \text{APC} = 0.85,\; \text{APS} = 0.15"),
                S("Break-even by formula", math=r"Y = \frac{a}{1 - b} = \frac{40}{0.25} = 160"),
                S("Pattern", text="MPC stays at 0.75, but APC falls as income rises, because autonomous consumption is spread over a larger income. APC > MPC whenever a > 0."),
            ]),
            H("What shifts consumption and saving"),
            T("Income moves us ALONG the function. Other factors SHIFT it. Answer such questions in a **directional** way: say which way the factor moves and what it does to consumption (the Board's 2023 report criticised answers that were not directional)."),
            KEY("Determinants of consumption (and so of saving)", "", cards=[
                ["Wealth", "A rise in wealth (land, houses, shares) raises consumption at every income."],
                ["Interest rates", "A rise in interest rates makes credit dearer and saving more rewarding, so consumption tends to fall."],
                ["Credit availability", "Easier access to loans (microfinance, salary advances) raises consumption."],
                ["Expectations", "Fear of job loss or of future price rises changes spending now."],
                ["Income distribution", "The poor have a higher MPC than the rich, so redistribution towards the poor raises total consumption."],
                ["Taxes and social security", "Higher income tax lowers disposable income; better pensions and health cover reduce the need for precautionary saving."]]),
            T("Factors that would raise household saving in Cameroon include higher real deposit rates, more bank and microfinance branches and mobile-money savings products, confidence in financial institutions, stable prices, rising incomes and weaker pressure from family obligations on spending."),
            H("Investment"),
            D("**Investment** is spending on new capital goods (machines, buildings, roads) and additions to stocks. **Autonomous investment** does not depend on the current level of income; **induced investment** rises when income rises.", title="Definition"),
            D("The **marginal efficiency of capital (MEC)** is the rate of return expected on an extra unit of capital: the discount rate that makes the present value of its expected yields equal to its cost. Keynes argued that firms invest while the MEC exceeds the rate of interest.", title="Definition"),
            F(r"PV = \frac{R_1}{1 + r} + \frac{R_2}{(1 + r)^2} + \dots + \frac{R_n}{(1 + r)^n}", title="Present value of expected yields"),
            EX("Worked example 2: should the firm buy the machine?", intro="A bakery in Douala can buy an oven for FCFA 1 000 000. It expects net yields of 600 000 at the end of each of the next two years, then nothing. The interest rate is 10%. Should it invest? What if the rate rises to 15%?", steps=[
                S("Present value at 10%", math=r"\frac{600\,000}{1.10} + \frac{600\,000}{1.10^2} = 545\,455 + 495\,868 = 1\,041\,322"),
                S("Decision at 10%", text="PV is greater than the cost of 1 000 000, so the investment is worthwhile."),
                S("Present value at 15%", math=r"\frac{600\,000}{1.15} + \frac{600\,000}{1.15^2} = 975\,425"),
                S("Decision at 15%", text="PV is now below the cost, so the oven is not worth buying. The MEC lies between 10% and 15% (about 13%)."),
            ]),
            T("Ranking all possible projects by their MEC gives a downward-sloping MEC (investment demand) schedule: lower interest rates make more projects worthwhile, so planned investment rises."),
            KEY("Determinants of private investment (directional)", "", cards=[
                ["Interest rate", "A fall in interest rates lowers the cost of borrowing and raises investment."],
                ["Expected demand and profit", "Optimistic expectations ('animal spirits', in Keynes's phrase) raise investment."],
                ["Cost of capital goods", "A fall in the price of machines raises the MEC and investment."],
                ["Technology", "New techniques create profitable projects."],
                ["Government policy", "Tax allowances, stable rules and good infrastructure raise investment; insecurity and red tape lower it."],
                ["Changes in income", "Rising demand needs more capacity: the accelerator (next lesson)."]]),
            MISTAKE("Mixing up APC and MPC", "APC = C / Y uses totals; MPC = change in C / change in Y uses changes. With a positive intercept they are different numbers."),
            MISTAKE("Explaining determinants as a list", "Write 'a fall in interest rates raises investment because ...'. A factor named without its direction and effect earns little."),
            QUIZ("C = 120 + 0.8Y. At Y = 1 000, what is the APS?",
                 ["0.2", "0.08", "0.92", "0.8"], 1,
                 "C = 920, so S = 80 and APS = 80 / 1 000 = 0.08.",
                 hint="Find S first, then divide by Y.",
                 feedback=["That is the MPS, not the APS.", "", "That is the APC.", "That is the MPC."]),
            QUIZ("A project costs 1 100 000 and yields 1 100 000 after one year only. At which interest rate is it NOT worth undertaking?",
                 ["Any positive rate", "Only rates above 10%", "Only a zero rate", "Rates below 5%"], 0,
                 "The PV of 1 100 000 received in a year is less than 1 100 000 at any positive rate, so the MEC is 0%.",
                 hint="Compare the yield with the cost: what return does the project give?",
                 feedback=["", "The project earns no return at all, so any positive rate beats it.", "At a zero rate the PV just equals the cost; at any positive rate it is less.", "Even at low rates the PV is below cost."]),
            TIP("Paper 2 has asked for the determinants of private-sector investment; Paper 3 has asked candidates to justify from a diagram why investment is autonomous or induced, and for factors raising household saving in Cameroon. An investment line that is flat is autonomous; one that slopes upward from a positive intercept has both an autonomous part (the intercept) and an induced part (the slope).", title="Exam link"),
            PQ("C = 120 + 0.8Y. Find the APC and APS at Y = 1 000 and Y = 1 500 and comment.",
               "At 1 000: C = 920, APC = 0.92, APS = 0.08. At 1 500: C = 1 320, APC = 0.88, APS = 0.12. As income rises, APC falls and APS rises, while MPC stays 0.8: richer people save a larger share of income."),
            PQ("A machine costs 1 000 000 and yields 1 100 000 after one year. Will a firm buy it if the interest rate is 8%? If it is 12%?",
               "PV at 8% = 1 100 000 / 1.08 = 1 018 519 > 1 000 000: buy. PV at 12% = 982 143 < 1 000 000: do not buy. The MEC is 10%."),
            PQ("Explain four factors that could increase the level of household saving in Cameroon.",
               "Directional points: (1) higher real interest rates on deposits reward saving; (2) wider access to banks, microfinance and mobile-money savings accounts makes saving easier and safer; (3) rising disposable incomes raise saving because MPS > 0; (4) stable prices protect the value of savings; also, confidence in financial institutions, and saving for education or housing goals."),
            PQ("Discuss the view that the rate of interest is the main determinant of investment.",
               "Plan: explain the MEC schedule: a lower rate makes more projects profitable, so investment rises. Counter-points: expectations of demand and profit can shift the MEC strongly (in a slump, low rates may not revive investment); the accelerator ties investment to changes in output; in Cameroon, access to credit, collateral, infrastructure, energy supply and the business climate may matter more than the rate itself; much public investment does not respond to interest rates. Conclude: the interest rate matters, but mainly at the margin; expectations and the business environment often dominate."),
            SUM("C = a + bY: a is autonomous consumption, b is the MPC; S = -a + (1 - b)Y.",
                "MPC + MPS = 1 and APC + APS = 1; APC falls as income rises when a > 0.",
                "Wealth, interest rates, credit, expectations, distribution and taxes shift consumption and saving.",
                "Investment is autonomous or induced; firms invest while the MEC exceeds the rate of interest.",
                "Expectations, costs, technology and policy also drive investment; answer determinants directionally."),
        ],
    ),
    # ================================================================ 4. Multiplier and accelerator
    lesson(
        module=M1, topic="The multiplier and the accelerator",
        title="The multiplier and the accelerator",
        slug="ecu1-multiplier-accelerator",
        minutes=25,
        summary="How a change in an injection changes income by a multiple, k = 1/(1 - MPC) = 1/MPW, the limits of the multiplier in a developing economy, the accelerator and how the two interact.",
        objectives=[
            "Explain the multiplier process round by round and derive k = 1/(1 - MPC)",
            "Calculate the open-economy multiplier k = 1/MPW and the change in income",
            "Explain the accelerator and calculate induced investment from changes in output",
            "Evaluate both theories, especially for an economy such as Cameroon's",
        ],
        key_concepts=["Multiplier", "Marginal propensity to withdraw", "Rounds of spending", "Accelerator",
                      "Capital-output ratio", "Net and gross investment", "Multiplier-accelerator interaction"],
        blocks=[
            H("Introduction"),
            T("Suppose the government spends FCFA 200 billion building a road in the East Region. The construction firms pay workers and suppliers, who spend part of their new income in shops and markets; the traders spend part of theirs, and so on. "
              "The final rise in national income is larger than the first 200 billion. This is the **multiplier**. Its partner, the **accelerator**, explains why investment swings so strongly when output changes."),
            H("The multiplier process"),
            D("The **multiplier (k)** is the number by which a change in an injection (I, G or X) is multiplied to give the final change in equilibrium national income: change in Y = k x change in injection.", title="Definition"),
            EX("Worked example 1: rounds of spending", intro="Closed economy without government, MPC = 0.8. Investment rises by 200 (billion FCFA). Trace the first rounds and find the total rise in income.", steps=[
                S("Round 1", text="The 200 spent on investment goods is income for the people who make them: +200."),
                S("Round 2", math=r"0.8 \times 200 = 160", text="They spend 80% of it; this is new income for others."),
                S("Rounds 3 and 4", math=r"0.8 \times 160 = 128,\quad 0.8 \times 128 = 102.4"),
                S("After four rounds", math=r"200 + 160 + 128 + 102.4 = 590.4", text="The rounds keep shrinking."),
                S("Sum of all rounds", math=r"200(1 + 0.8 + 0.8^2 + \dots) = \frac{200}{1 - 0.8} = 1\,000"),
            ], check=r"k = \frac{1}{1 - 0.8} = 5,\quad 5 \times 200 = 1\,000"),
            T("The rounds form a geometric series with first term the injection and common ratio the MPC. Its sum gives the formula."),
            F(r"k = \frac{1}{1 - \text{MPC}} = \frac{1}{\text{MPS}}", title="Closed economy without government"),
            F(r"k = \frac{1}{\text{MPS} + \text{MPT} + \text{MPM}} = \frac{1}{\text{MPW}}", title="Open economy with government"),
            T("**MPW**, the marginal propensity to withdraw, is the fraction of each extra franc of national income that leaks out as saving (MPS), taxes (MPT) or imports (MPM). The larger the leakages, the smaller the multiplier."),
            EX("Worked example 2: the open-economy multiplier", intro="Of each extra 100 francs of national income, 10 is saved, 20 paid in tax and 20 spent on imports. Government spending rises by 300. Find k and the change in income.", steps=[
                S("MPW", math=r"0.1 + 0.2 + 0.2 = 0.5"),
                S("Multiplier", math=r"k = \frac{1}{0.5} = 2"),
                S("Change in income", math=r"\Delta Y = 2 \times 300 = 600"),
                S("Check the leakages", math=r"0.5 \times 600 = 300", text="In the new equilibrium, extra leakages (300) equal the extra injection (300)."),
            ]),
            KEY("Why the multiplier may be small in practice", "Evaluation points the examiners value, with Cameroon in mind.", cards=[
                ["High import content", "Much new income is spent on imported goods, so MPM is high and k is low."],
                ["Supply constraints", "If farms and firms cannot raise output (energy, roads, skills), extra spending raises prices instead of real income."],
                ["Time lags", "The rounds take months or years; the full effect is never reached at once."],
                ["Informal and cash saving", "Money hoarded at home or sent to relatives abroad also leaks."],
                ["Crowding out", "Government borrowing to finance spending can raise interest rates and reduce private investment."],
                ["Works both ways", "A FALL in an injection (e.g. lower oil export earnings) reduces income by a multiple."]]),
            H("The accelerator"),
            D("The **accelerator principle** states that net investment depends on the CHANGE in output (or sales), not on its level: I(net) = v x change in Y, where **v** is the **capital-output ratio** (the value of capital needed to produce one unit of output a year).", title="Definition"),
            F(r"I_{net} = v\,(Y_t - Y_{t-1}) \qquad I_{gross} = I_{net} + \text{replacement investment}", title="Accelerator"),
            EX("Worked example 3: a firm's investment", intro="A cement firm needs 2 units of capital for each unit of annual output (v = 2). It replaces 20 units of worn-out capital every year. Sales over six years are 100, 100, 110, 125, 130, 130. Find net and gross investment each year from year 2.", steps=[
                S("Capital required (2 x sales)", math=r"200,\ 200,\ 220,\ 250,\ 260,\ 260"),
                S("Net investment (change in capital)", math=r"0,\ 20,\ 30,\ 10,\ 0"),
                S("Gross investment (net + 20)", math=r"20,\ 40,\ 50,\ 30,\ 20"),
                S("Lesson", text="In year 5 sales still rise (by 5) but grow more slowly than before (15), and gross investment FALLS from 50 to 30. Investment depends on the rate of change of output, so it is far more volatile than output."),
            ]),
            CODE("""Year   Sales   Capital needed   Net investment   Gross investment
1      100     200              -                -
2      100     200              0                20
3      110     220              20               40
4      125     250              30               50
5      130     260              10               30
6      130     260              0                20""", "text", title="Table 1. The accelerator at work (v = 2, replacement 20 a year)"),
            KEY("Limits of the accelerator", "", cards=[
                ["Spare capacity", "If firms have idle machines, they meet higher demand without new investment."],
                ["Expectations", "Firms invest only if they believe the rise in demand will last."],
                ["Capital-goods supply", "The machine makers (often abroad) may not deliver at once."],
                ["v is not fixed", "Technology and relative prices change the capital needed per unit of output."],
                ["Finance", "Firms may lack the credit to buy the capital the theory says they need."]]),
            H("Multiplier and accelerator together"),
            T("A rise in investment raises income through the multiplier; the rise in income induces more investment through the accelerator, which raises income again. When growth slows, induced investment falls, which cuts income through the multiplier. "
              "Paul Samuelson's multiplier-accelerator model used this interaction to explain the upswings and downswings of the **trade cycle**, which you will study later in the course."),
            MISTAKE("Using 1/MPC as the multiplier", "The multiplier is 1/(1 - MPC) = 1/MPS in a closed economy without government. With MPC 0.8, k = 5, not 1.25."),
            MISTAKE("Leaving out taxes and imports in an open economy", "If the question gives MPT and MPM, use k = 1/(MPS + MPT + MPM)."),
            MISTAKE("Linking the accelerator to the level of output", "Net investment depends on the CHANGE in output. Constant output, however high, means zero net investment."),
            QUIZ("MPS = 0.15, MPT = 0.25, MPM = 0.1. Exports rise by 40. By how much does equilibrium income rise?",
                 ["20", "80", "160", "267"], 1,
                 "MPW = 0.5, so k = 2 and the rise in income is 2 x 40 = 80.",
                 hint="Add the three withdrawal propensities first.",
                 feedback=["This multiplies by MPW instead of dividing by it.", "", "This leaves out taxes: 40 / (0.15 + 0.1) = 160.", "This uses 1/MPS only, ignoring taxes and imports."]),
            QUIZ("Under the accelerator, what happens to net investment if output grows by the same amount every year?",
                 ["It rises each year", "It stays constant", "It falls to zero", "It becomes negative"], 1,
                 "Net investment = v x change in output; if the change is the same each year, net investment is constant.",
                 hint="Net investment depends on the change in output.",
                 feedback=["It rises only if the growth of output speeds up.", "", "It falls to zero only if output stops growing.", "It turns negative only if output falls."]),
            TIP("The multiplier formula and simple accelerator tables are common in Paper 1. In Paper 2, explain the process in rounds, give the formula, and then evaluate the size of the multiplier in a developing economy.", title="Exam link"),
            PQ("In a closed economy without government, MPC = 0.75. Investment rises by 50. Find the multiplier and the change in income.",
               "k = 1/(1 - 0.75) = 4. Change in income = 4 x 50 = 200."),
            PQ("The government wants to raise national income by 600. MPW is 1/3. By how much must it raise its spending?",
               "k = 1/MPW = 3. Required rise in G = 600 / 3 = 200."),
            PQ("A firm's capital-output ratio is 3. Its output rises from 400 to 420 and then to 430. Find net investment in each of the two years.",
               "Year 1: 3 x 20 = 60. Year 2: 3 x 10 = 30. Output still grew, but more slowly, so net investment halved."),
            PQ("Assess the usefulness of the multiplier for planning public investment in Cameroon.",
               "Plan: explain the multiplier: an injection raises income by k times; derive k = 1/MPW. Usefulness: gives an estimate of the income and jobs created by projects such as roads or dams, and warns that cuts also have multiplied effects. Limits: high MPM (imported equipment and consumer goods) and taxes reduce k; supply bottlenecks turn extra demand into inflation; time lags; leakage through cash hoarding and transfers abroad; crowding out if financed by borrowing. Conclude: useful as a guide to direction, but the size must be estimated with care, and projects that use local labour and materials give larger multipliers."),
            SUM("An injection raises income in shrinking rounds; total change = k x change in injection.",
                "k = 1/(1 - MPC) = 1/MPS in a closed economy; k = 1/MPW = 1/(MPS + MPT + MPM) in an open economy.",
                "High imports, supply constraints, lags and crowding out make the real multiplier smaller.",
                "Accelerator: net investment = v x change in output; investment swings more than output.",
                "Multiplier and accelerator interact to produce cycles in income."),
        ],
    ),
    # ================================================================ 5. Inflationary and deflationary gaps
    lesson(
        module=M1, topic="Inflationary and deflationary gaps",
        title="Inflationary and deflationary gaps, and the paradox of thrift",
        slug="ecu1-inflationary-deflationary-gaps",
        minutes=25,
        summary="Full-employment income, deflationary and inflationary gaps, how big a change in spending is needed to close them, and the paradox of thrift with autonomous and induced investment.",
        objectives=[
            "Define and draw deflationary and inflationary gaps on the Keynesian cross",
            "Calculate the size of a gap from the output gap and the multiplier",
            "Suggest and evaluate policies to close each gap",
            "Explain the paradox of thrift with a saving-investment diagram, including its assumptions",
        ],
        key_concepts=["Full-employment income", "Deflationary gap", "Inflationary gap", "Output gap",
                      "Paradox of thrift", "Autonomous and induced investment", "Fallacy of composition"],
        blocks=[
            H("Introduction"),
            T("The Keynesian model shows that equilibrium income can settle anywhere. It may be too low to employ everyone who wants work, as in many economies in the 1930s, or spending may be so high that output cannot keep up and prices rise. "
              "The two situations are measured by **gaps** between equilibrium and **full-employment income (Yf)**, the output the economy produces when its resources are fully used."),
            H("The deflationary gap"),
            D("A **deflationary gap** (recessionary gap) is the amount by which aggregate expenditure falls short of the level needed to give full-employment income. On the Keynesian cross it is the VERTICAL distance, at Yf, between the 45-degree line and the AE line.", title="Definition"),
            IMG("alecu1-gaps.svg", alt="Keynesian cross with AE1 crossing the 45-degree line at Ye, left of full-employment income Yf. At Yf a brown vertical segment between the 45-degree line and AE1 is labelled deflationary gap. A dashed AE2 passes through the 45-degree line at Yf.", caption="Figure 1. A deflationary gap. AE must rise from AE1 to AE2 to reach Yf."),
            T("Do not confuse the gap with the **output gap**, the HORIZONTAL distance Yf - Ye. The two are linked by the multiplier: closing a deflationary gap of size d raises income by k x d."),
            F(r"\text{Deflationary gap} = \frac{Y_f - Y_e}{k}", title="Size of the gap"),
            EX("Worked example 1: a deflationary gap", intro="Equilibrium income is 800, full-employment income is 1 000 and the MPC is 0.75 (closed economy, no government). How large is the deflationary gap?", steps=[
                S("Multiplier", math=r"k = \frac{1}{1 - 0.75} = 4"),
                S("Output gap", math=r"1\,000 - 800 = 200"),
                S("Deflationary gap", math=r"\frac{200}{4} = 50", text="Aggregate expenditure must rise by 50 at every income level."),
            ], check=r"4 \times 50 = 200"),
            H("The inflationary gap"),
            D("An **inflationary gap** is the amount by which aggregate expenditure EXCEEDS the level needed for full-employment income. Real output cannot rise above Yf in the short run, so the excess demand pulls up prices (demand-pull inflation).", title="Definition"),
            EX("Worked example 2: an inflationary gap", intro="At current spending plans the model gives an equilibrium of 1 200 in money terms, but full-employment income is 1 000. The multiplier is 4. Find the inflationary gap.", steps=[
                S("Excess over full employment", math=r"1\,200 - 1\,000 = 200"),
                S("Inflationary gap", math=r"\frac{200}{4} = 50", text="Spending must fall by 50 at every income level to remove the inflationary pressure."),
            ]),
            KEY("Closing the gaps", "", cards=[
                ["Deflationary gap", "Raise AE: higher government spending, tax cuts, lower interest rates, policies to raise exports."],
                ["Inflationary gap", "Reduce AE: lower government spending, higher taxes, higher interest rates, credit restrictions."],
                ["Evaluation", "Yf is hard to measure; policies act with lags; in a developing economy the main constraint may be supply (energy, skills, roads), so raising demand may cause inflation before full employment."]]),
            H("The paradox of thrift"),
            D("The **paradox of thrift** is the idea that if all households try to save more, aggregate expenditure falls, national income falls, and total saving may not rise at all (it may even fall). What is wise for one household can harm the economy as a whole, an example of the **fallacy of composition**.", title="Definition"),
            IMG("alecu1-paradox-thrift.svg", alt="Saving and investment against national income. An upward-sloping investment line I starts above zero. Saving line S1 crosses it at E1 above Y1. A higher saving line S2 crosses I at E2 above a lower income Y2, where saving is lower than at E1.", caption="Figure 2. The paradox of thrift. Households try to save more (S1 to S2); income falls from Y1 to Y2 and saving ends up lower."),
            EX("Worked example 3: the paradox with induced investment", intro="S = -100 + 0.25Y and I = 50 + 0.05Y. Households decide to save 50 more at every income, so S = -50 + 0.25Y. Find income and saving before and after.", steps=[
                S("Before: S = I", math=r"-100 + 0.25Y = 50 + 0.05Y \Rightarrow 0.2Y = 150 \Rightarrow Y = 750"),
                S("Saving before", math=r"S = -100 + 0.25(750) = 87.5"),
                S("After: S = I", math=r"-50 + 0.25Y = 50 + 0.05Y \Rightarrow 0.2Y = 100 \Rightarrow Y = 500"),
                S("Saving after", math=r"S = -50 + 0.25(500) = 75"),
                S("Conclusion", text="Income fell by 250 and total saving FELL from 87.5 to 75. Lower income reduced induced investment, and in equilibrium saving equals investment."),
            ]),
            T("If investment were purely autonomous (say I = 100), the same rise in thriftiness would cut income from 800 to 600, while saving would end unchanged at 100. Either way, the attempt to save more fails and income falls."),
            KEY("Assumptions and evaluation", "State the assumptions; the Board's 2023 report asked for them.", cards=[
                ["Assumptions", "Spare capacity and unemployment (a deflationary situation); extra saving is not turned into extra investment; prices and interest rates fixed; a closed economy without government in the simple model."],
                ["When it fails", "If the extra saving lowers interest rates and is lent to firms that invest, or if the economy is at full employment, more saving can finance more investment and long-run growth."],
                ["Developing economies", "Low saving limits investment (see growth models later), so thrift is usually encouraged; the paradox is a short-run warning about demand, not a rule against saving."]]),
            MISTAKE("Measuring the gap horizontally", "The deflationary or inflationary gap is the VERTICAL distance at Yf. The horizontal distance Yf - Ye is the output gap, k times larger."),
            MISTAKE("Explaining the paradox without the diagram", "When a diagram is given, use its labels: name the shift S1 to S2, the new equilibrium, the fall in income and what happens to saving."),
            QUIZ("Equilibrium income is 600, full-employment income is 900 and the multiplier is 3. What is the deflationary gap?",
                 ["300", "900", "100", "200"], 2,
                 "Output gap 300 divided by k = 3 gives 100.",
                 hint="Divide the output gap by the multiplier.",
                 feedback=["That is the output gap, the horizontal distance.", "This multiplies the output gap by k instead of dividing.", "", "This divides by 1.5 instead of the multiplier 3."]),
            QUIZ("In the paradox of thrift, why can total saving FALL when households try to save more?",
                 ["Lower income reduces induced investment, and in equilibrium saving equals investment", "Banks refuse to accept deposits", "Interest rates rise sharply", "Taxes rise automatically"], 0,
                 "Saving must end up equal to investment; if investment falls with income, so does saving.",
                 hint="What must saving equal in equilibrium?",
                 feedback=["", "The model says nothing about banks refusing deposits.", "In the simple model interest rates are held constant.", "The simple model has no government."]),
            TIP("Paper 3 data questions may give you a saving-investment or Keynesian cross diagram and ask you to identify a gap or the paradox of thrift, state assumptions, or say from the diagram whether investment is autonomous or induced. Paper 2 essays ask you to explain the gaps and evaluate policies to close them.", title="Exam link"),
            PQ("Full-employment income is 1 500, equilibrium income is 1 200 and MPW = 0.25. Find the deflationary gap and suggest two policies to close it.",
               "k = 4; output gap = 300; gap = 300 / 4 = 75. Policies: raise government spending by 75 (or cut taxes enough to raise C by 75), lower interest rates to encourage investment."),
            PQ("With S = -60 + 0.2Y and I = 40 (autonomous), find equilibrium income. Then saving rises by 20 at every income. Find the new income and saving.",
               "Before: -60 + 0.2Y = 40, Y = 500, S = 40. After: -40 + 0.2Y = 40, Y = 400, S = 40. Income falls by 100 and saving is unchanged: the paradox of thrift."),
            PQ("Distinguish between an inflationary gap and a deflationary gap.",
               "A deflationary gap is the shortfall of AE below the level needed for full employment, whereas an inflationary gap is the excess of AE above that level. The first causes unemployment; the second, with output fixed at Yf, causes demand-pull inflation. Both are measured vertically at Yf."),
            PQ("Discuss whether a government should encourage households to save more during a recession.",
               "Plan: explain the paradox of thrift with S and I diagram; more saving lowers AE and income, may not raise total saving. Counter-arguments: saving finances investment if banks lend it; in the long run, saving supports capital accumulation and growth (important for developing economies); the paradox needs spare capacity and investment that does not respond to lower interest rates. Conclude: in a deep recession, encouraging spending is the better short-run aim; saving should be encouraged when the economy is near full capacity or in the long run."),
            SUM("Full-employment income Yf is the target; gaps are measured vertically at Yf.",
                "Deflationary gap = shortfall of AE; inflationary gap = excess of AE; gap = output gap / k.",
                "Close a deflationary gap by raising AE, an inflationary gap by reducing AE; supply limits and lags complicate both.",
                "Paradox of thrift: trying to save more cuts income, and saving may not rise (it falls when investment is induced).",
                "It assumes spare capacity and saving not turned into investment."),
        ],
    ),
    # ================================================================ 6. Money and the money supply
    lesson(
        module=M2, topic="Money and the money supply",
        title="Money, its measures and what determines the money supply",
        slug="ecu1-money-supply",
        minutes=23,
        summary="Narrow and broad money (M0, M1, M2, M3), near money and liquidity, the monetary base and the money multiplier m = (1 + c)/(c + r), and whether the money supply is exogenous or endogenous.",
        objectives=[
            "Distinguish narrow from broad money and calculate M1, M2 and M3 from data",
            "Explain near money and the spectrum of liquidity",
            "Use the money multiplier to link the monetary base to the money supply",
            "Discuss whether the central bank can fully control the money supply",
        ],
        key_concepts=["Money supply", "Narrow money", "Broad money", "Near money", "Liquidity",
                      "Monetary base", "Currency-deposit ratio", "Money multiplier", "Exogenous and endogenous money"],
        blocks=[
            H("Introduction"),
            T("At O Level you studied the functions of money: a medium of exchange, a unit of account, a store of value and a standard of deferred payment. At A Level the question becomes: **how much money is there**, and who decides? "
              "The answer matters because, as later lessons show, the quantity of money affects interest rates, spending and prices. In the CEMAC zone the monetary authority is BEAC, which publishes regular statistics on the money supply of each member state."),
            D("The **money supply** (money stock) is the total amount of money in the economy at a point in time: notes and coins held by the public plus deposits at banks that can be used, or quickly converted, to make payments.", title="Definition"),
            H("Measures of money"),
            T("Because many assets are 'almost money', economists use several measures, from narrow to broad. Exact definitions differ between countries and textbooks (check your textbook), but the idea is the same: each broader measure adds less liquid assets."),
            KEY("A typical classification", "Check your textbook for the exact definitions it uses; BEAC's statistics mainly use M1 and M2 (check the current BEAC publications).", cards=[
                ["M0 (monetary base)", "Notes and coins in circulation plus banks' reserves held at the central bank."],
                ["M1 (narrow money)", "Currency held by the public plus demand (current, sight) deposits, usable at once for payments."],
                ["M2", "M1 plus time and savings deposits ('quasi-money'): they need notice or a short wait before they can be spent."],
                ["M3 (broad money)", "M2 plus other liquid deposits and instruments, for example large deposits and short-term certificates, depending on the definition used."]]),
            D("**Liquidity** is the ease and speed with which an asset can be turned into a means of payment without loss of value. Cash is perfectly liquid; land is very illiquid. **Near money** is an asset that is highly liquid but is not itself used to pay, such as a savings deposit or a Treasury bill.", title="Definition"),
            EX("Worked example 1: measuring money", intro="Data for an economy (billion FCFA, invented): currency held by the public 1 200; demand deposits 2 300; time and savings deposits 1 500; other liquid deposits and certificates 600. Find M1, M2 and M3 using the classification above.", steps=[
                S("M1", math=r"1\,200 + 2\,300 = 3\,500"),
                S("M2", math=r"3\,500 + 1\,500 = 5\,000"),
                S("M3", math=r"5\,000 + 600 = 5\,600"),
                S("Comment", text="Narrow money is 62.5% of broad money here. In economies where many people hold cash and few have bank accounts, currency is a large share of M1."),
            ]),
            T("Mobile money is an interesting case. Balances in mobile-money wallets are backed by deposits that the operators hold in partner banks, so they are already counted in bank deposits; the wallets mainly make existing money move faster. How they should be treated in the statistics is a technical question for the central bank (check current practice)."),
            H("The money multiplier"),
            T("The central bank controls the **monetary base** (B): currency plus bank reserves. Commercial banks lend part of their deposits (next lesson), so the money supply is a multiple of the base. Two ratios set the size of that multiple: the public's **currency-deposit ratio** (c) and the banks' **reserve ratio** (r)."),
            F(r"M = C_p + D, \qquad B = C_p + R, \qquad c = \frac{C_p}{D}, \qquad r = \frac{R}{D}", title="Definitions"),
            F(r"m = \frac{M}{B} = \frac{1 + c}{c + r}", title="The money multiplier"),
            EX("Worked example 2: from base to money supply", intro="The monetary base is 2 000. The public holds currency equal to 25% of its deposits (c = 0.25) and banks keep reserves of 10% of deposits (r = 0.1). Find the money multiplier, the money supply and deposits.", steps=[
                S("Multiplier", math=r"m = \frac{1 + 0.25}{0.25 + 0.1} = \frac{1.25}{0.35} = 3.57"),
                S("Money supply", math=r"M = 3.57 \times 2\,000 \approx 7\,143"),
                S("Deposits", math=r"D = \frac{B}{c + r} = \frac{2\,000}{0.35} \approx 5\,714", text="Currency held by the public is 0.25 x 5 714 = 1 429; 1 429 + 5 714 = 7 143."),
                S("Comparison", text="If the public held no cash (c = 0), m = 1/r = 10. Holding cash reduces the multiplier a lot, which is typical of cash-based economies."),
            ], check=r"1\,429 + 571 = 2\,000 = B"),
            KEY("What changes the money supply", "", cards=[
                ["Central bank", "Changes the base (lending to banks, open market operations, buying foreign exchange) and the required reserve ratio."],
                ["Commercial banks", "Hold excess reserves when they are cautious, so r is above the legal minimum and m falls."],
                ["The public", "Holds more cash when it distrusts banks or when banking is hard to reach, raising c and lowering m."],
                ["Government and the external sector", "Government borrowing from the central bank and export earnings converted into local currency add to the base."]]),
            H("Exogenous or endogenous?"),
            T("In the simple multiplier model the money supply is **exogenous**: the central bank fixes the base and the ratios, and the money stock follows. Many economists argue that money is largely **endogenous**: banks make loans when creditworthy borrowers ask for them, and the central bank then supplies the reserves needed, while controlling mainly the price (the interest rate). "
              "In practice both views have truth: the central bank strongly influences the money supply but cannot fix it exactly, because c and r depend on the behaviour of the public and of banks."),
            MISTAKE("Counting cash in bank vaults as part of the money supply", "The money supply counts currency held by the PUBLIC plus deposits. Cash in banks' tills is part of their reserves, already backing the deposits."),
            MISTAKE("Treating near money as money", "A time deposit is near money: it is very liquid, but you usually cannot pay a supplier with it directly. It enters M2, not M1."),
            QUIZ("Currency held by the public is 800, demand deposits 1 700 and savings deposits 900. What is M1?",
                 ["3 400", "1 700", "2 500", "2 600"], 2,
                 "M1 = currency + demand deposits = 800 + 1 700 = 2 500.",
                 hint="Narrow money: what can be spent immediately.",
                 feedback=["That includes savings deposits, which belong to M2.", "That leaves out the currency held by the public.", "", "This adds the currency to savings deposits instead of demand deposits."]),
            QUIZ("What happens to the money multiplier if people decide to keep more cash outside banks?",
                 ["It rises", "It falls", "It does not change", "It becomes equal to 1/r"], 1,
                 "A higher c means less is deposited and re-lent, so m = (1 + c)/(c + r) falls (for r < 1).",
                 hint="Cash outside banks cannot be lent again.",
                 feedback=["More cash outside banks shortens the chain of lending.", "", "c appears in the formula, so the multiplier changes.", "m equals 1/r only when c = 0."]),
            TIP("Paper 1 often tests the measures of money, near money and simple multiplier calculations. In Paper 2, link the money supply to the work of commercial banks and to BEAC's instruments.", title="Exam link"),
            PQ("The monetary base is 1 500, c = 0.2 and r = 0.1. Find the money multiplier and the money supply.",
               "m = 1.2 / 0.3 = 4. Money supply = 4 x 1 500 = 6 000."),
            PQ("Explain what is meant by liquidity and rank cash, a savings deposit, a Treasury bill and a house by liquidity.",
               "Liquidity is the ease of converting an asset into a means of payment quickly and without loss. Most to least liquid: cash, savings deposit, Treasury bill, house (some textbooks place Treasury bills before savings deposits; argue your ranking)."),
            PQ("Why may the money multiplier be smaller in Cameroon than in an economy where most payments are made through banks?",
               "Many people hold and use cash and have no bank account, so c is high; banks may keep excess reserves because of limited good lending opportunities and risk, so r is high. Both reduce m = (1 + c)/(c + r)."),
            PQ("Discuss whether the central bank can control the money supply.",
               "Plan: yes, partly: it controls the base and the reserve requirement, so through m it influences M. But: c depends on the public's trust in banks and access to banking; banks hold excess reserves or lend more depending on demand for loans and risk (endogenous money); government borrowing and foreign exchange inflows change the base; financial innovation creates new near monies. Conclude: the central bank influences rather than fixes the money supply, which is one reason many central banks target interest rates instead."),
            SUM("Narrow money (M1) = currency held by the public + demand deposits; broad measures add less liquid deposits; definitions vary.",
                "Near money is highly liquid but not used directly for payment.",
                "Money supply = m x monetary base, with m = (1 + c)/(c + r).",
                "More cash holding (higher c) or more reserves (higher r) reduce the multiplier.",
                "The money supply is partly exogenous and partly endogenous: the central bank influences but does not fix it."),
        ],
    ),
    # ================================================================ 7. Commercial banks and credit creation
    lesson(
        module=M2, topic="Commercial banks and credit creation",
        title="Commercial bank balance sheets and the credit creation multiplier",
        slug="ecu1-commercial-banks-credit-creation",
        minutes=25,
        summary="A commercial bank's balance sheet, the conflict between liquidity and profitability, credit creation by a single bank and by the whole system, the credit multiplier 1/r, and how cash drains and excess reserves limit it.",
        objectives=[
            "Read a commercial bank's balance sheet and calculate cash and liquidity ratios",
            "Explain the conflict between liquidity, profitability and security",
            "Show credit creation with balance sheets for a single bank and the banking system",
            "Calculate the credit multiplier with and without a cash drain and evaluate its limits",
        ],
        key_concepts=["Bank balance sheet", "Liquidity ratio", "Cash ratio", "Liquidity-profitability conflict",
                      "Excess reserves", "Credit multiplier", "Cash drain", "Fractional reserve banking"],
        blocks=[
            H("Introduction"),
            T("A commercial bank in Douala or Yaounde takes deposits from customers and lends to traders, farmers and firms. At O Level you saw how lending turns one deposit into many. At A Level you must read a bank's **balance sheet**, explain the trade-off a banker faces, and show exactly how the banking system creates credit and what stops it."),
            H("The balance sheet"),
            D("A bank's **balance sheet** lists its liabilities (what it owes: mostly customers' deposits, plus shareholders' capital and reserves) and its assets (what it owns or is owed: cash, balances at the central bank, short-term lending, securities and loans). Total assets equal total liabilities.", title="Definition"),
            CODE("""LIABILITIES                       ASSETS
Share capital and reserves  120   Cash in tills                      50
Demand deposits             600   Balances at the central bank       70
Time and savings deposits   400   Money at call and short notice     60
                                  Treasury and commercial bills      90
                                  Investments (securities)          150
                                  Loans and advances                650
                                  Premises and equipment             50
TOTAL                      1 120  TOTAL                           1 120""", "text", title="Table 1. A simplified commercial bank balance sheet (billion FCFA, invented for practice)"),
            T("The assets are listed in order of **liquidity**, from cash (most liquid, earns nothing) down to loans and advances (least liquid, earn the highest interest). Note that customers' deposits are LIABILITIES of the bank: it owes the money back. The Board's 2023 report noted candidates confusing this bank balance sheet with the balance of payments; keep the two apart."),
            EX("Worked example 1: ratios from the balance sheet", intro="Using Table 1, find the cash ratio (cash plus balances at the central bank, over deposits) and the liquid assets ratio (cash, central bank balances, money at call and bills, over deposits).", steps=[
                S("Total deposits", math=r"600 + 400 = 1\,000"),
                S("Cash ratio", math=r"\frac{50 + 70}{1\,000} = 12\%"),
                S("Liquid assets ratio", math=r"\frac{50 + 70 + 60 + 90}{1\,000} = 27\%"),
                S("Meaning", text="If many depositors withdraw at once, the bank can meet 12% from cash at once and 27% from assets it can turn into cash within days."),
            ]),
            KEY("The banker's dilemma", "A bank pursues three aims that pull against each other.", cards=[
                ["Liquidity", "Enough cash to meet withdrawals at any time, or the bank fails and confidence collapses."],
                ["Profitability", "Loans and investments earn interest; cash earns nothing. Shareholders want profit."],
                ["Security", "Loans must be safe: collateral, good borrowers, spreading of risk."],
                ["The conflict", "The most profitable assets are the least liquid and often the riskiest; the bank must balance its portfolio."]]),
            H("Credit creation"),
            D("**Credit creation** is the process by which banks, keeping only a fraction of deposits as reserves (**fractional reserve banking**), lend the rest; the loans are spent and redeposited, creating new deposits across the banking system.", title="Definition"),
            EX("Worked example 2: one bank and the whole system", intro="A customer deposits FCFA 1 000 000 of new cash. Every bank keeps a 10% reserve ratio and lends the rest; all loans are redeposited. Show the first bank's position and the system total.", steps=[
                S("First bank after the deposit", text="Liabilities: deposits +1 000 000. Assets: cash +1 000 000. Required reserve = 100 000, so excess reserves = 900 000."),
                S("What a single bank can lend", math=r"1\,000\,000 - 100\,000 = 900\,000", text="A single bank can lend only its excess reserves, because the borrower will spend the money and it will leave the bank."),
                S("Whole system: credit multiplier", math=r"\frac{1}{r} = \frac{1}{0.10} = 10"),
                S("Total deposits and new loans", math=r"1\,000\,000 \times 10 = 10\,000\,000,\quad 10\,000\,000 - 1\,000\,000 = 9\,000\,000", text="The system as a whole can create 9 million of new loans because each loan returns to some bank as a deposit."),
            ], check=r"0.10 \times 10\,000\,000 = 1\,000\,000 \text{ (all new cash held as reserves)}"),
            F(r"\text{Credit multiplier} = \frac{1}{r} \qquad \text{Total deposits} = \frac{\text{new cash deposited}}{r}", title="Simple credit multiplier"),
            H("Cash drains"),
            T("If borrowers keep part of each loan in cash instead of depositing it, the chain is shorter. Suppose each bank keeps reserve ratio r and a fraction d of every loan stays outside the banks as cash. Each new deposit is then (1 - r)(1 - d) times the previous one."),
            F(r"\text{Total deposits} = \frac{\text{initial deposit}}{1 - (1 - r)(1 - d)}", title="With a cash drain"),
            EX("Worked example 3: a 20% cash drain", intro="Initial deposit 1 000 (thousand FCFA), r = 0.1, and 20% of every loan is kept as cash (d = 0.2). Find total deposits.", steps=[
                S("Ratio between successive deposits", math=r"(1 - 0.1)(1 - 0.2) = 0.72"),
                S("Total deposits", math=r"\frac{1\,000}{1 - 0.72} = \frac{1\,000}{0.28} \approx 3\,571"),
                S("Compare", text="Without the drain, deposits would reach 10 000. The cash drain cuts the multiplier from 10 to about 3.6."),
                S("Check where the cash went", math=r"\text{reserves } 357 + \text{cash outside banks } 643 = 1\,000", text="All the original cash ends up either as reserves or in people's pockets."),
            ]),
            KEY("Limits on credit creation (evaluation)", "", cards=[
                ["Reserve and liquidity rules", "Set by the central bank (in CEMAC, BEAC sets reserve requirements and COBAC, the regional banking commission, supervises prudential ratios; check the current rules)."],
                ["Cash drains", "High in economies where many transactions are in cash."],
                ["Demand for loans", "Banks cannot lend if few creditworthy borrowers apply."],
                ["Risk and collateral", "Lack of land titles or reliable information on borrowers makes banks cautious; they hold excess reserves or government securities instead."],
                ["Central bank policy", "Higher policy rates or credit limits reduce lending."]]),
            MISTAKE("Saying a single bank can lend 1/r times its new deposit", "A single bank can lend only its excess reserves. The multiplier applies to the banking SYSTEM, where loans come back as deposits."),
            MISTAKE("Putting deposits on the assets side", "Deposits are what the bank owes to customers: liabilities. Loans to customers are assets."),
            QUIZ("A bank must keep 8% reserves. It receives a new cash deposit of 500. With no cash drain, what is the maximum increase in deposits in the whole banking system?",
                 ["540", "4 000", "6 250", "5 750"], 2,
                 "Credit multiplier = 1/0.08 = 12.5; total deposits = 500 x 12.5 = 6 250.",
                 hint="Divide the new deposit by the reserve ratio.",
                 feedback=["This simply adds 8% to the deposit.", "This multiplies by 8 instead of by 1/0.08.", "", "This is the increase in LOANS (6 250 - 500), not in deposits."]),
            QUIZ("Which asset on a bank's balance sheet usually earns the highest return but is the least liquid?",
                 ["Cash in tills", "Balances at the central bank", "Loans and advances", "Money at call"], 2,
                 "Loans earn the highest interest but cannot be turned into cash quickly.",
                 hint="Think of the liquidity-profitability trade-off.",
                 feedback=["Cash is perfectly liquid and earns nothing.", "These are very liquid and earn little or nothing.", "", "Money at call is very liquid and earns a low rate."]),
            TIP("Paper 1 often asks for credit-multiplier calculations; Paper 2 essays ask how banks create credit and what limits it. Show a short table or T-accounts and state the formula; then evaluate the limits, using the cash-based nature of the economy as an example.", title="Exam link"),
            PQ("A bank holds deposits of 2 400 and must keep 15% as reserves. It holds 480 in reserves. How much can it lend now?",
               "Required reserves = 0.15 x 2 400 = 360. Excess reserves = 480 - 360 = 120, so it can lend 120."),
            PQ("A new deposit of 800 is made. r = 0.05 and borrowers keep 25% of each loan as cash. Find total deposits in the system.",
               "Ratio = (0.95)(0.75) = 0.7125. Total deposits = 800 / (1 - 0.7125) = 800 / 0.2875 = 2 783 (to the nearest unit)."),
            PQ("Explain the conflict between liquidity and profitability faced by a commercial bank.",
               "Liquid assets (cash, central bank balances) let the bank meet withdrawals but earn little or nothing; profitable assets (loans, investments) earn interest but cannot be turned into cash quickly and carry risk. Holding too much cash lowers profit; holding too little risks a run. The bank spreads its assets across the spectrum and follows the central bank's ratios."),
            PQ("Discuss the factors that limit the ability of commercial banks in Cameroon to create credit.",
               "Plan: explain credit creation and the multiplier 1/r. Limits: reserve requirements set by BEAC and prudential rules supervised by COBAC; cash drain because many transactions are in cash; low demand from creditworthy borrowers; lack of collateral and borrower information; banks' preference for safe government securities and excess reserves; central bank interest rates. Evaluate: in many CEMAC economies banks have often held excess liquidity, suggesting that the binding limit is lending opportunities and risk rather than reserves; reforms such as credit information systems and land titling would help."),
            SUM("Deposits are liabilities; cash, central bank balances, bills, investments and loans are assets, in falling order of liquidity.",
                "Banks balance liquidity, profitability and security.",
                "A single bank lends its excess reserves; the system can create deposits up to new cash / r.",
                "A cash drain d cuts the multiplier: total deposits = initial / [1 - (1 - r)(1 - d)].",
                "Reserve rules, cash drains, loan demand, risk and central bank policy limit credit creation."),
        ],
    ),
    # ================================================================ 8. Demand for money and interest rates
    lesson(
        module=M2, topic="The demand for money and interest rates",
        title="Liquidity preference: active and idle balances and the rate of interest",
        slug="ecu1-demand-for-money-interest",
        minutes=25,
        summary="Keynes's three motives for holding money, active and idle balances, why bond prices and interest rates move in opposite directions, money market equilibrium, the liquidity trap and the link to investment.",
        objectives=[
            "Explain the transactions, precautionary and speculative motives for holding money",
            "Distinguish active from idle balances and draw a diagram for each",
            "Explain the inverse link between bond prices and interest rates",
            "Find money market equilibrium and analyse a change in the money supply, including the liquidity trap",
        ],
        key_concepts=["Demand for money", "Liquidity preference", "Transactions motive", "Precautionary motive",
                      "Speculative motive", "Active balances", "Idle balances", "Bond prices", "Liquidity trap"],
        blocks=[
            H("Introduction"),
            T("Why would anyone hold money, which earns little or no interest, instead of putting it into bonds or deposits that pay interest? Keynes answered that people value **liquidity**: money can be spent at once and its value in francs does not fall when interest rates change. "
              "Holding money therefore has a benefit (liquidity) and a cost (the interest given up). In the Lower Sixth you met liquidity preference as a theory of the rate of interest; here we look closely at the demand for money itself and how it links money to the rest of the economy."),
            D("The **demand for money** is the amount of wealth people and firms wish to hold in the form of money (cash and demand deposits) rather than in interest-earning assets. Keynes called it **liquidity preference** (L).", title="Definition"),
            H("Three motives"),
            KEY("Keynes's motives for holding money", "", cards=[
                ["Transactions motive", "Money to pay for everyday purchases between pay days. Rises with income (and the price level)."],
                ["Precautionary motive", "Money for unexpected spending: illness, a funeral, a business emergency. Also rises with income."],
                ["Speculative motive", "Money held instead of bonds, waiting for a better time to buy them. Falls as the interest rate rises."]]),
            D("**Active balances** (L1) are money held for the transactions and precautionary motives: they are used in spending and depend mainly on income, not on the interest rate. **Idle balances** (L2) are money held for the speculative motive: they are not used for spending and vary inversely with the rate of interest.", title="Definition", note="Against the interest rate, active balances are a vertical line that shifts right when income rises, whereas idle balances slope downward. Use a conjunction such as 'whereas' when you distinguish them."),
            IMG("alecu1-active-idle.svg", alt="Two panels. Left: interest rate against active balances; L1 is a vertical line, and a dashed vertical line further right shows L1 at a higher income Y2. Right: interest rate against idle balances; L2 slopes down and becomes almost flat at low interest rates, labelled liquidity trap.", caption="Figure 1. (a) Active balances do not depend on the interest rate but rise with income. (b) Idle balances fall as the interest rate rises."),
            H("Why idle balances fall when interest rates rise"),
            T("Bonds pay a fixed amount of interest each year (the coupon). If market interest rates rise, new bonds pay more, so existing bonds with a fixed coupon are worth less: their price falls. For a bond that pays a coupon for ever (a perpetuity):"),
            F(r"\text{Bond price} = \frac{\text{annual coupon}}{r}", title="Price of a perpetual bond"),
            EX("Worked example 1: bond prices and interest rates", intro="A government bond pays FCFA 5 000 a year for ever. Find its price when the market interest rate is 5%, 8% and 4%.", steps=[
                S("At 5%", math=r"\frac{5\,000}{0.05} = 100\,000"),
                S("At 8%", math=r"\frac{5\,000}{0.08} = 62\,500", text="A holder who bought at 100 000 makes a capital loss of 37 500."),
                S("At 4%", math=r"\frac{5\,000}{0.04} = 125\,000", text="A capital gain of 25 000."),
                S("The speculative choice", text="When interest rates are HIGH (bond prices low), people expect rates to fall and bond prices to rise, so they buy bonds and hold little idle money. When rates are LOW (bond prices high), they expect rates to rise and bond prices to fall, so they hold money to avoid a capital loss."),
            ]),
            H("Money market equilibrium"),
            T("Total demand for money is L = L1 + L2. The supply of money (Ms) is set by the central bank and the banks; in the simple model it does not depend on the interest rate and is drawn vertical. The interest rate settles where the demand for money equals the supply."),
            IMG("alecu1-money-market.svg", alt="Interest rate against quantity of money. A downward-sloping liquidity preference curve L flattens at low rates. Vertical money supply Ms1 crosses it at r1; a larger supply Ms2 crosses it at a lower rate r2.", caption="Figure 2. A rise in the money supply from Ms1 to Ms2 lowers the interest rate from r1 to r2."),
            EX("Worked example 2: equilibrium interest rate", intro="Active balances L1 = 0.2Y and national income Y = 5 000. Idle balances L2 = 1 000 - 100r (r in percent). The money supply is 1 600. Find the interest rate. Then the money supply rises to 1 700.", steps=[
                S("Active balances", math=r"L_1 = 0.2 \times 5\,000 = 1\,000"),
                S("Equilibrium", math=r"1\,000 + 1\,000 - 100r = 1\,600 \Rightarrow 100r = 400 \Rightarrow r = 4\%"),
                S("New money supply", math=r"2\,000 - 100r = 1\,700 \Rightarrow r = 3\%"),
                S("Meaning", text="The extra money is held as idle balances only if people are paid a lower interest rate; they buy bonds, bond prices rise and the rate falls."),
            ], check=r"0.2(5\,000) + 1\,000 - 100(3) = 1\,700"),
            H("From money to spending, and the liquidity trap"),
            T("A lower interest rate makes more investment projects worthwhile (MEC above r), so investment and, through the multiplier, income rise. This is the Keynesian **transmission mechanism**: more money, lower interest rate, more investment, higher income. Higher income then raises active balances."),
            D("The **liquidity trap** is a situation in which interest rates are so low that everyone expects them to rise; people are willing to hold any extra money as idle balances, so increases in the money supply fail to lower the interest rate further. The L curve becomes flat.", title="Definition"),
            KEY("Why monetary policy may be weak (Keynesian view)", "", cards=[
                ["Liquidity trap", "Extra money is hoarded, so r does not fall."],
                ["Interest-inelastic investment", "Even if r falls, pessimistic firms may not invest."],
                ["Developing economies", "Thin bond markets, credit rationing and cash holding weaken the link between money, interest rates and spending."]]),
            KEY("Factors that reduce the demand for active balances (directional)", "A Paper 2 question has asked for these.", cards=[
                ["Lower income or output", "Fewer transactions need less money."],
                ["Lower price level", "Each transaction needs fewer francs."],
                ["More frequent pay", "Paying wages weekly instead of monthly cuts the average balance held."],
                ["Wider use of credit and electronic payment", "Cards, mobile money and credit lines let people pay without holding large balances."],
                ["Better access to quick borrowing or insurance", "Less need for precautionary balances."]]),
            MISTAKE("Saying bond prices rise when interest rates rise", "They move in OPPOSITE directions: price = coupon / r."),
            MISTAKE("Drawing active balances sloping downward against the interest rate", "Active balances depend on income; against r they are a vertical line that shifts right when income rises."),
            QUIZ("A perpetual bond pays 6 000 a year. The interest rate falls from 6% to 5%. What happens to its price?",
                 ["It falls from 100 000 to 83 333", "It rises from 100 000 to 120 000", "It stays at 6 000", "It rises by 1%, to 101 000"], 1,
                 "6 000 / 0.06 = 100 000 and 6 000 / 0.05 = 120 000: a lower rate raises the bond price.",
                 hint="Price = coupon / r.",
                 feedback=["This gets the direction wrong: lower rates mean higher bond prices.", "", "6 000 is the coupon, not the price.", "A one-point fall in r from 6% changes the price by far more than 1%."]),
            QUIZ("Which motive for holding money is most sensitive to the rate of interest?",
                 ["Transactions", "Precautionary", "Speculative", "Unit of account"], 2,
                 "Speculative (idle) balances are held instead of bonds and fall as the interest rate rises.",
                 hint="Which balances are held instead of bonds?",
                 feedback=["Transactions balances depend mainly on income.", "Precautionary balances depend mainly on income.", "", "Unit of account is a function of money, not a motive for holding it."]),
            TIP("The Board's 2023 report described the Paper 2 question on active and idle balances as the worst-answered: candidates did not draw the diagrams, did not use conjunctions to make the distinction, and did not give directional answers. Draw both panels of Figure 1, and write each factor as 'a fall in X reduces active balances because ...'.", title="Exam link"),
            PQ("Distinguish, with the help of diagrams, between active and idle balances.",
               "Active balances are held for the transactions and precautionary motives and depend on income, whereas idle balances are held for the speculative motive and depend inversely on the interest rate. Diagram (a): vertical L1 against r, shifting right with income. Diagram (b): downward-sloping L2 against r, flattening at low rates (liquidity trap)."),
            PQ("L1 = 0.25Y, Y = 4 000, L2 = 800 - 50r (r in percent), money supply 1 600. Find the equilibrium interest rate.",
               "L1 = 1 000. 1 000 + 800 - 50r = 1 600, so 50r = 200 and r = 4%."),
            PQ("Explain four factors that would reduce the demand for active balances in an economy.",
               "A fall in national income (fewer transactions); a fall in the price level (each purchase needs fewer francs); more frequent payment of wages (smaller average balance between pay days); wider use of credit facilities, cards and mobile payments (people can pay without holding money); easier access to emergency credit or insurance (less precautionary money)."),
            PQ("Assess the claim that an increase in the money supply will always lower interest rates and raise investment.",
               "Plan: explain the transmission mechanism with the money market diagram: Ms rises, r falls, investment rises via the MEC. Limits: liquidity trap (extra money held idle, r does not fall); investment may be interest-inelastic if expectations are poor; banks may not pass on lower rates; in a developing economy credit rationing, cash holding and thin bond markets weaken the links; if prices rise, real money balances may not rise (monetarist view). Conclude: usually true in direction but not always in size, which is why monetary policy is often said to be like 'pushing on a string' in a slump."),
            SUM("People hold money for transactions, precautionary and speculative motives.",
                "Active balances (L1) depend on income; idle balances (L2) fall as the interest rate rises.",
                "Bond prices and interest rates move inversely: price = coupon / r.",
                "The interest rate is set where L = Ms; more money lowers r unless the economy is in a liquidity trap.",
                "Lower r raises investment and income, but expectations and credit conditions can weaken the effect."),
        ],
    ),
    # ================================================================ 9. Quantity theory of money
    lesson(
        module=M2, topic="The quantity theory of money",
        title="The quantity theory of money: MV = PT and its critics",
        slug="ecu1-quantity-theory-of-money",
        minutes=24,
        summary="Fisher's equation of exchange MV = PT, the Cambridge version M = kPY, the assumptions that turn the identity into a theory of prices, the monetarist view and the Keynesian criticisms, with calculations.",
        objectives=[
            "State and explain the Fisher equation MV = PT and the Cambridge equation M = kPY",
            "Explain the assumptions that make the quantity theory a theory of the price level",
            "Calculate the price level, velocity and inflation using the equations",
            "Evaluate the theory from monetarist and Keynesian points of view",
        ],
        key_concepts=["Equation of exchange", "Velocity of circulation", "Quantity theory of money",
                      "Cambridge equation", "Monetarism", "Neutrality of money", "Keynesian critique"],
        blocks=[
            H("Introduction"),
            T("Whenever governments have printed money fast to pay their bills, prices have risen fast. The **quantity theory of money** gives the oldest explanation of this link. It starts from an identity that is always true and adds assumptions that turn it into a theory of the price level."),
            H("The equation of exchange"),
            D("Irving Fisher's **equation of exchange** states MV = PT, where M is the money supply, V the **velocity of circulation** (the average number of times each unit of money is spent in a period), P the average price level and T the number of transactions.", title="Definition"),
            F(r"MV \equiv PT", title="Fisher's equation of exchange"),
            T("Both sides measure total spending: the money stock times how often it is spent equals the value of everything bought. As written, it is an **identity**, true by definition, because V is measured as PT / M. Since T is hard to measure, the equation is usually written with real national output Y instead: MV = PY, where PY is nominal GDP."),
            EX("Worked example 1: price level and velocity", intro="(a) M = 500, V = 6, T = 1 000. Find P. (b) Nominal GDP is 18 000 and the money supply is 4 500. Find the income velocity of money.", steps=[
                S("(a) Price level", math=r"P = \frac{MV}{T} = \frac{500 \times 6}{1\,000} = 3"),
                S("(b) Velocity", math=r"V = \frac{PY}{M} = \frac{18\,000}{4\,500} = 4", text="On average each franc is spent four times a year on final output."),
            ]),
            H("From identity to theory"),
            KEY("The classical assumptions", "These turn MV = PT into the quantity THEORY: changes in M cause proportional changes in P.", cards=[
                ["V is stable", "Velocity depends on slow-changing habits and institutions (how often people are paid, banking practices)."],
                ["T (or Y) is fixed in the short run", "The economy is at full employment; output depends on real factors, not on money."],
                ["M is exogenous", "The money supply is set by the authorities, independently of P."],
                ["Causation runs from M to P", "Money is the active variable; prices respond."]]),
            EX("Worked example 2: a 20% rise in money", intro="With V = 6 and T = 1 000 fixed, the money supply rises from 500 to 600. Find the new price level.", steps=[
                S("New price level", math=r"P = \frac{600 \times 6}{1\,000} = 3.6"),
                S("Percentage change", math=r"\frac{3.6 - 3}{3} = 20\%", text="Prices rise in the same proportion as the money supply: money is **neutral** for real output."),
            ]),
            H("The Cambridge version"),
            D("The **Cambridge equation** M = kPY looks at the DEMAND for money: people wish to hold a fraction k of their nominal income as money. Here k = 1/V. If k is stable, the demand for money is a stable function of nominal income.", title="Definition"),
            EX("Worked example 3: the Cambridge equation and growth rates", intro="(a) k = 0.25, P = 2, Y = 10 000. How much money do people wish to hold? (b) The money supply grows by 10% a year, velocity is constant and real output grows by 4%. What inflation rate does the theory predict?", steps=[
                S("(a) Money demanded", math=r"M = 0.25 \times 2 \times 10\,000 = 5\,000", text="This is the same as V = 4 in Fisher's form."),
                S("(b) Growth-rate form (approximate)", math=r"\%\Delta M + \%\Delta V \approx \%\Delta P + \%\Delta Y"),
                S("Substitute", math=r"10 + 0 \approx \%\Delta P + 4 \Rightarrow \%\Delta P \approx 6\%"),
                S("Exact check", math=r"\frac{1.10}{1.04} - 1 = 0.0577 \approx 5.8\%"),
            ]),
            H("Monetarism and its critics"),
            T("Milton Friedman and the monetarists restated the theory in the 1950s and 1960s: the demand for money is a stable function of a few variables, so velocity is predictable; in the long run money affects only prices. Their policy conclusion was that the central bank should let the money supply grow at a steady rate close to the growth of real output, to keep inflation low."),
            KEY("Keynesian criticisms", "", cards=[
                ["V is not stable", "Velocity changes with interest rates, confidence and financial innovation (mobile money, cards). If V falls when M rises, P need not rise."],
                ["Output is not fixed", "With unemployment and spare capacity, more money (through lower interest rates) can raise real output instead of prices."],
                ["Causation can run from P to M", "Firms facing higher costs borrow more; banks lend; the money supply follows prices (endogenous money)."],
                ["Liquidity trap", "Extra money may be held idle, raising k (lowering V)."]]),
            T("**Evaluation.** In the long run and in cases of very rapid money growth (hyperinflations), the evidence for a close link between money and prices is strong. Over short periods and at low inflation, the link is loose, which is why most central banks now target interest rates or inflation directly instead of the money supply. "
              "For the CEMAC zone, the fixed exchange rate with the euro also ties domestic prices to import prices, and limits on central bank lending to governments are partly a quantity-theory safeguard against inflation."),
            MISTAKE("Treating MV = PT as proof that money causes inflation", "As an identity it shows only that spending = value of purchases. The theory needs the assumptions (stable V, fixed T, exogenous M)."),
            MISTAKE("Confusing k and V", "k = 1/V. If V = 5, people hold one fifth of annual nominal income as money, so k = 0.2."),
            QUIZ("M = 2 000, V = 5 and real output Y = 4 000. What is the price level?",
                 ["0.4", "1.6", "2.5", "10 000"], 2,
                 "P = MV / Y = 10 000 / 4 000 = 2.5.",
                 hint="Rearrange MV = PY for P.",
                 feedback=["This is Y / MV, the reciprocal.", "This divides 4 000 by 2 500 by mistake.", "", "This is MV, total spending, not the price level."]),
            QUIZ("Under the strict quantity theory, if the money supply doubles, what happens?",
                 ["Real output doubles", "The price level doubles", "Velocity halves", "Nothing changes"], 1,
                 "With V and T fixed, P must rise in proportion to M.",
                 hint="Which variables are held constant by assumption?",
                 feedback=["Output is assumed fixed at full employment.", "", "V is assumed stable; if it halved, prices would not change at all.", "Total spending doubles, so something must change: P."]),
            TIP("Paper 1 tests MV = PT calculations and the assumptions. In Paper 2, state the equation, explain each symbol, give the assumptions, then evaluate with the Keynesian criticisms and with evidence on inflation.", title="Exam link"),
            PQ("Nominal GDP is 24 000 and the money supply is 6 000. Find V and k.",
               "V = 24 000 / 6 000 = 4. k = 1/V = 0.25."),
            PQ("Money grows by 12%, velocity falls by 2% and real output grows by 5%. Estimate inflation using the growth-rate form.",
               "%M + %V = %P + %Y, so 12 - 2 = %P + 5 and %P is about 5%. (Exact: 1.12 x 0.98 / 1.05 - 1 = 4.5%.)"),
            PQ("Explain the assumptions needed to turn the equation of exchange into the quantity theory of money.",
               "V is constant or stable (it depends on payment habits and institutions); T or Y is fixed because the economy is at full employment; M is determined independently by the authorities; and the direction of causation runs from M to P. Then P is proportional to M."),
            PQ("Evaluate the quantity theory of money as an explanation of inflation.",
               "Plan: explain MV = PT, the assumptions and the prediction that P moves with M. Strengths: strong long-run link and clear in hyperinflations; explains why financing deficits by printing money is inflationary; underlies monetarist policy. Weaknesses: V is unstable in the short run; output can change when there is spare capacity; money may respond to prices (endogenous money); cost-push and imported inflation (important in an open economy with a fixed exchange rate) are not explained by M. Conclude: a good long-run guide and a warning against monetary financing, but not a full theory of inflation in the short run."),
            SUM("Equation of exchange: MV = PT (or MV = PY), an identity.",
                "With stable V, fixed output and exogenous M, the price level is proportional to the money supply.",
                "Cambridge form: M = kPY with k = 1/V; growth form: %M + %V = %P + %Y approximately.",
                "Monetarists: steady money growth keeps inflation low; money is neutral in the long run.",
                "Keynesians: V is unstable, output can change and causation may run from prices to money."),
        ],
    ),
    # ================================================================ 10. BEAC and monetary policy
    lesson(
        module=M2, topic="The central bank (BEAC) and monetary policy",
        title="BEAC and monetary policy in the CEMAC zone",
        slug="ecu1-beac-monetary-policy",
        minutes=25,
        summary="The aims and instruments of monetary policy, how BEAC conducts it for the six CEMAC states under a fixed exchange rate, the transmission mechanism, calculations with reserve requirements and open market operations, and an evaluation of its effectiveness.",
        objectives=[
            "State the objectives of monetary policy and BEAC's main objective",
            "Explain the instruments of monetary policy and calculate their effect on bank lending",
            "Trace the transmission mechanism from the policy rate to prices and output",
            "Evaluate the effectiveness of monetary policy in the CEMAC zone",
        ],
        key_concepts=["Monetary policy", "BEAC", "Monetary Policy Committee", "Policy interest rate",
                      "Reserve requirements", "Open market operations", "Transmission mechanism",
                      "Fixed exchange rate", "COBAC", "Monetary union"],
        blocks=[
            H("Introduction"),
            T("Cameroon does not have its own national central bank. It shares the **Bank of Central African States (BEAC)**, with headquarters in Yaounde, with the Central African Republic, Chad, the Republic of Congo, Equatorial Guinea and Gabon: the six members of CEMAC. "
              "All six use the CFA franc of Central Africa (XAF), pegged to the euro at 655.957 FCFA per euro. At O Level you learnt the functions of a central bank; this lesson asks how BEAC uses monetary policy and how well it can work in a monetary union with a fixed exchange rate."),
            D("**Monetary policy** is the use by the central bank of interest rates, the supply of money and credit, and related instruments to achieve macroeconomic objectives, above all price stability.", title="Definition"),
            H("Objectives"),
            T("BEAC's statutes give **monetary stability** as its main objective: low inflation and a sound external value of the currency, which under the peg means keeping enough foreign exchange reserves. Without harming that objective, BEAC supports the general economic policies of the member states. "
              "CEMAC's convergence framework includes an inflation criterion (check the current rules for the exact figure). Policy decisions are taken by BEAC's **Monetary Policy Committee** (Comite de Politique Monetaire)."),
            H("Instruments"),
            KEY("The main instruments (names and rates change: check BEAC's current position)", "", cards=[
                ["Policy interest rate", "The rate at which BEAC lends liquidity to banks in its regular auctions (often referred to as the TIAO, taux d'interet des appels d'offres), with a higher rate on its marginal lending facility. Raising it makes bank funding dearer."],
                ["Reserve requirements", "Banks must keep a percentage of deposits on account at BEAC. Raising the ratio reduces the credit multiplier and banks' free liquidity."],
                ["Liquidity operations (open market type)", "BEAC injects liquidity through auctions against eligible securities, or absorbs it (for example by taking deposits from banks). Absorbing liquidity reduces banks' reserves and lending."],
                ["Limits on financing governments", "Direct central bank advances to member treasuries have been ended or frozen in recent reforms (check the current rules); this protects monetary stability."],
                ["Prudential supervision", "COBAC (the Banking Commission of Central Africa) supervises banks and sets prudential ratios; strictly this is regulation rather than monetary policy, but it affects credit."]]),
            EX("Worked example 1: raising the reserve requirement", intro="Banks hold deposits of 800 (billion FCFA) and reserves at BEAC of exactly 56, the 7% requirement. BEAC raises the requirement to 10%. (Teaching values, invented for practice, not BEAC's actual ratios.)", steps=[
                S("New required reserves", math=r"0.10 \times 800 = 80", text="Banks are 24 short."),
                S("Maximum deposits the existing reserves support", math=r"\frac{56}{0.10} = 560"),
                S("Fall in deposits if banks cannot find more reserves", math=r"800 - 560 = 240", text="A 24 shortfall, multiplied by 1/0.10 = 10, forces a contraction of 240 in deposits and lending over time."),
                S("In practice", text="Where banks hold large excess reserves, a rise in the requirement may only absorb surplus liquidity and change lending little."),
            ]),
            EX("Worked example 2: absorbing liquidity", intro="BEAC absorbs 15 (billion FCFA) of bank reserves through a liquidity-absorbing operation. The reserve ratio is 10% and banks have no excess reserves. What is the maximum effect on deposits?", steps=[
                S("Fall in reserves", math=r"15"),
                S("Credit multiplier", math=r"1 / 0.10 = 10"),
                S("Maximum fall in deposits", math=r"10 \times 15 = 150"),
            ]),
            H("The transmission mechanism"),
            T("A rise in the policy rate works through a chain: banks' funding costs rise, so they raise lending rates; borrowing for investment and consumption falls; aggregate demand falls; firms face weaker demand and raise prices less; inflation falls. Some effect also comes through expectations and asset prices. "
              "In a floating-rate country, a higher rate would also strengthen the currency; under the euro peg, this **exchange rate channel** is closed, but the policy rate helps to keep capital and reserves in the zone."),
            KEY("Evaluation: how effective is monetary policy in CEMAC?", "", cards=[
                ["Excess liquidity", "When banks hold large surplus reserves, changes in the policy rate and reserve ratio may barely affect lending."],
                ["Shallow financial system", "Many people and firms are outside the banking system; much trade is in cash; bond markets are thin, so interest rates reach few borrowers."],
                ["One policy, six economies", "Oil-exporting and non-oil members may need different policies (asymmetric shocks), but there is one rate."],
                ["The peg", "Monetary policy must protect reserves and the peg, so it largely follows the euro area's stance; it cannot devalue to boost exports."],
                ["Fiscal dominance", "If governments run large deficits, pressure on reserves can force tighter policy than domestic conditions need."],
                ["Strengths", "The peg and limits on financing governments have usually kept inflation in the zone low compared with many countries with their own floating currencies."]]),
            T("Supporters of the arrangement stress price stability and the discipline it imposes; critics argue that it limits policy freedom and that a fixed rate to the euro may not suit economies that depend on oil and commodity exports. This is a live debate: present both sides, with evidence, rather than taking a political position."),
            MISTAKE("Writing that BEAC sets Cameroon's monetary policy alone", "BEAC sets ONE policy for all six CEMAC states; Cameroon's national directorate of BEAC carries it out, but the decisions are regional."),
            MISTAKE("Listing instruments without the mechanism", "For each instrument, say what BEAC does, how it changes bank liquidity or the cost of credit, and the effect on spending and prices."),
            QUIZ("BEAC wants to reduce inflationary pressure. Which combination is consistent with that aim?",
                 ["Raise the policy rate and raise reserve requirements", "Lower the policy rate and lower reserve requirements", "Inject liquidity through auctions and raise advances to governments", "Devalue the CFA franc"], 0,
                 "Both measures make credit scarcer and dearer, reducing aggregate demand.",
                 hint="Tight monetary policy reduces money and credit.",
                 feedback=["", "These loosen policy and would add to inflation.", "These expand the money supply.", "Devaluation raises import prices and is not a monetary policy tool BEAC can use on its own."]),
            QUIZ("Why might a rise in BEAC's policy rate have only a small effect on bank lending in the CEMAC zone?",
                 ["Interest rates do not affect any borrower", "BEAC has no policy rate", "Banks hold large excess reserves and do not need to borrow from BEAC", "The CFA franc floats freely"], 2,
                 "If banks have plenty of their own liquidity, the cost of central bank funding hardly affects their lending decisions.",
                 hint="How does a policy rate reach banks' own lending decisions?",
                 feedback=["Formal-sector borrowers are affected; the point is about how strongly.", "BEAC does set a policy rate for its liquidity auctions.", "", "The CFA franc is pegged to the euro."]),
            TIP("The Board's 2023 report mentions a Paper 2 money-and-banking question on the functions of BEAC and the central bank. Paper 2 may also ask you to assess monetary policy; use CEMAC examples, and hedge specific rates and instrument names with 'check the current position'.", title="Exam link"),
            PQ("Banks hold deposits of 1 200 and reserves of 120 (no excess). The reserve requirement rises from 10% to 12%. Find the maximum deposits the existing reserves can support and the fall in deposits.",
               "120 / 0.12 = 1 000. Deposits must fall by 1 200 - 1 000 = 200 if banks cannot obtain more reserves."),
            PQ("Explain how BEAC's policy interest rate influences inflation.",
               "A higher policy rate raises banks' cost of funds; they raise lending rates; borrowing and spending by firms and households fall; aggregate demand falls; pressure on prices eases. It also discourages capital outflows and protects reserves supporting the peg. The effect is weaker where banks have excess liquidity or many people use cash."),
            PQ("State four instruments of monetary policy available to BEAC.",
               "Policy (auction) interest rate and marginal lending rate; reserve requirements; liquidity injection and absorption operations; limits on financing governments; and, through COBAC, prudential ratios that affect credit (names and rates: check the current position)."),
            PQ("Assess the effectiveness of monetary policy in the CEMAC zone.",
               "Plan: aims (monetary stability, reserves for the peg) and instruments with their mechanism. Effective in: keeping inflation relatively low; protecting the peg; disciplining government borrowing. Limits: excess bank liquidity weakens the rate channel; shallow financial markets and cash use; one rate for six different economies; no exchange rate tool; dependence on oil prices and fiscal policy. Conclude: effective for price stability, much less effective for steering output and employment, so fiscal and structural policies carry more of that burden."),
            SUM("BEAC is the central bank of the six CEMAC states; its main objective is monetary stability under the euro peg.",
                "Instruments: policy rate, reserve requirements, liquidity operations, limits on financing governments (check current names and rates).",
                "Higher rates and reserve ratios reduce credit and aggregate demand; changes in reserves are multiplied by 1/r.",
                "Transmission: policy rate, lending rates, spending, prices; the exchange rate channel is closed by the peg.",
                "Excess liquidity, cash use, one policy for six economies and the peg limit effectiveness."),
        ],
    ),
    # ================================================================ 11. Fiscal policy
    lesson(
        module=M3, topic="Fiscal policy",
        title="Fiscal policy: discretionary measures, automatic stabilisers and the multipliers",
        slug="ecu1-fiscal-policy",
        minutes=25,
        summary="Expansionary and contractionary fiscal policy, discretionary policy versus automatic stabilisers, the government spending, tax and balanced budget multipliers, and the limits of fiscal policy: lags, crowding out and revenue dependence.",
        objectives=[
            "Define fiscal policy and distinguish expansionary from contractionary policy",
            "Explain the difference between automatic stabilisers and discretionary fiscal policy",
            "Calculate the government spending, tax and balanced budget multipliers",
            "Evaluate fiscal policy, including time lags, crowding out and the situation of Cameroon",
        ],
        key_concepts=["Fiscal policy", "Expansionary and contractionary policy", "Automatic stabilisers",
                      "Discretionary fiscal policy", "Tax multiplier", "Balanced budget multiplier",
                      "Crowding out", "Time lags"],
        blocks=[
            H("Introduction"),
            T("Each year Parliament votes the Finance Law, which sets out what the government of Cameroon will collect in taxes and other revenue and what it will spend on salaries, roads, schools and debt. These choices change aggregate expenditure. "
              "In the Keynesian model of Module 1, the government can use them to close inflationary and deflationary gaps. This is **fiscal policy**."),
            D("**Fiscal policy** is the use of government spending, taxation and borrowing to influence aggregate demand, output, employment, prices and the distribution of income.", title="Definition"),
            KEY("Two directions", "", cards=[
                ["Expansionary (reflationary)", "Raise G and/or cut taxes; the budget moves towards deficit. Used to close a deflationary gap."],
                ["Contractionary (deflationary)", "Cut G and/or raise taxes; the budget moves towards surplus. Used to close an inflationary gap."]]),
            H("Automatic stabilisers and discretionary policy"),
            D("**Automatic stabilisers** are parts of the budget that change by themselves with the trade cycle, without any new decision, and so reduce fluctuations: tax revenue rises automatically in a boom and falls in a slump; spending on unemployment and social benefits does the opposite. **Discretionary fiscal policy** is a deliberate change in tax rates or spending decided by the government.", title="Definition"),
            EX("Worked example 1: an automatic stabiliser", intro="Income tax takes 20% of each extra franc of income. National income falls by 1 000 (billion FCFA) in a recession. What happens to tax revenue and disposable income?", steps=[
                S("Fall in tax revenue", math=r"0.20 \times 1\,000 = 200", text="This happens without any change in the law."),
                S("Fall in disposable income", math=r"1\,000 - 200 = 800", text="Households lose 800, not 1 000, so consumption falls less and the recession is milder."),
                S("Limit", text="Stabilisers only soften fluctuations; they do not remove a gap. In economies with few people paying income tax and little social protection (as in much of Cameroon's informal sector), they are weak."),
            ]),
            H("The fiscal multipliers"),
            T("Government spending is an injection, so a change in G has the full multiplier effect. A change in taxes acts first on disposable income, and only the part that would have been spent (MPC) enters the first round, so the tax multiplier is smaller and negative."),
            F(r"k_G = \frac{1}{1 - \text{MPC}} \qquad k_T = \frac{-\text{MPC}}{1 - \text{MPC}}", title="Spending and tax multipliers (closed economy, lump-sum taxes)"),
            EX("Worked example 2: spending, taxes and a balanced budget", intro="Closed economy, MPC = 0.8, lump-sum taxes. Find the change in income if (a) G rises by 100, (b) taxes rise by 100, (c) both happen together.", steps=[
                S("(a) Spending multiplier", math=r"k_G = \frac{1}{0.2} = 5,\quad \Delta Y = 5 \times 100 = 500"),
                S("(b) Tax multiplier", math=r"k_T = \frac{-0.8}{0.2} = -4,\quad \Delta Y = -4 \times 100 = -400"),
                S("(c) Balanced budget change", math=r"500 - 400 = 100", text="Income rises by exactly the change in G: the **balanced budget multiplier** is 1."),
            ], check=r"k_G + k_T = 5 - 4 = 1"),
            D("The **balanced budget multiplier** states that an equal rise in government spending and taxes raises national income by the amount of the rise (multiplier = 1, in the simple closed-economy model with lump-sum taxes), because spending enters the flow in full while part of the tax would have been saved.", title="Definition"),
            H("Limits of fiscal policy"),
            KEY("Evaluation points", "", cards=[
                ["Time lags", "Recognition lag (seeing the problem), decision lag (budget process, Parliament), and impact lag (projects take time). Policy may act when the problem has passed."],
                ["Crowding out", "Borrowing to finance a deficit may raise interest rates or absorb bank lending, reducing private investment. Strongest near full employment."],
                ["Imports", "A high MPM means much extra spending leaks abroad."],
                ["Supply constraints", "If output cannot respond, extra demand raises prices."],
                ["Revenue volatility", "When revenue depends on oil and commodity prices, spending often has to be cut when world prices fall: fiscal policy can become pro-cyclical."],
                ["Debt and rules", "High debt, CEMAC convergence criteria and IMF-supported programmes limit room for deficits (check the current rules)."],
                ["Implementation", "Low execution rates of investment budgets and weak project management reduce the real effect of planned spending."]]),
            T("**Keynesian and monetarist views.** Keynesians see fiscal policy as a powerful tool to close deflationary gaps, especially when monetary policy is weak. Monetarists and new classical economists stress crowding out, lags and the risk that households save tax cuts because they expect higher taxes later; they prefer stable rules and supply-side measures."),
            MISTAKE("Using the same multiplier for taxes as for spending", "A tax cut of 100 raises spending by only MPC x 100 in the first round. With MPC 0.8, the tax multiplier is 4 (in size), not 5."),
            MISTAKE("Calling all deficits 'expansionary policy'", "A deficit can rise automatically in a recession (stabilisers) without any new decision. Distinguish automatic from discretionary changes."),
            QUIZ("MPC = 0.75 in a closed economy with lump-sum taxes. The government cuts taxes by 40. What is the change in national income?",
                 ["+160", "+120", "+40", "-120"], 1,
                 "Tax multiplier = -0.75/0.25 = -3; a tax CUT of 40 gives -3 x (-40) = +120.",
                 hint="The tax multiplier is -MPC/(1 - MPC); a cut is a negative change.",
                 feedback=["This uses the spending multiplier 4 instead of the tax multiplier.", "", "That would be the balanced budget multiplier result, not a tax cut alone.", "A tax CUT raises income; the sign is wrong."]),
            QUIZ("Which is an example of an automatic stabiliser?",
                 ["Progressive income tax revenue falling as incomes fall in a recession", "A new road programme announced in the Finance Law", "A rise in the VAT rate voted by Parliament", "A one-off grant to schools"], 0,
                 "Revenue changes by itself as income changes, without any new decision.",
                 hint="Automatic means no new decision is needed.",
                 feedback=["", "This is a deliberate (discretionary) decision.", "A change in rates is discretionary.", "A one-off grant is discretionary."]),
            TIP("Paper 2 essays ask you to explain and evaluate fiscal policy; Paper 1 tests the multipliers. Link fiscal policy to the deflationary and inflationary gaps of Module 1, and use Cameroonian points (oil revenue, investment budget execution, debt rules) in evaluation.", title="Exam link"),
            PQ("MPC = 0.9 (closed economy, lump-sum taxes). Find the change in income if G rises by 50 and taxes rise by 50.",
               "k_G = 10, so +500; k_T = -9, so -450. Net change = +50: the balanced budget multiplier is 1."),
            PQ("Distinguish between automatic stabilisers and discretionary fiscal policy.",
               "Automatic stabilisers are budget items that change by themselves with income (tax revenue, benefits) and soften the cycle, whereas discretionary policy is a deliberate change in tax rates or spending decided by the government to influence the economy."),
            PQ("A deflationary gap of 60 exists and MPC = 0.8 (closed economy). By how much must the government raise G, or cut taxes, to close it?",
               "The gap is measured in spending, so G must rise by 60 (which raises Y by 5 x 60 = 300). A tax cut must raise consumption by 60, so taxes must fall by 60 / 0.8 = 75."),
            PQ("Discuss the effectiveness of fiscal policy as a means of reducing unemployment in Cameroon.",
               "Plan: explain expansionary policy and the multiplier. For: public investment in roads, energy and schools raises demand and future capacity; Keynesian theory supports it when there is spare capacity. Against: high import content and taxes lower the multiplier; much unemployment and underemployment is structural or in the informal sector; time lags and low execution of investment budgets; dependence on oil revenue and debt limits; crowding out of private credit. Conclude: effective when well targeted (labour-intensive, local-content projects) and combined with supply-side policies; less effective as general demand stimulus."),
            SUM("Fiscal policy uses G, T and borrowing to influence aggregate demand; it can be expansionary or contractionary.",
                "Automatic stabilisers soften cycles without new decisions; discretionary policy is deliberate.",
                "k_G = 1/(1 - MPC); k_T = -MPC/(1 - MPC); the balanced budget multiplier is 1 in the simple model.",
                "Lags, crowding out, imports, supply limits and revenue volatility weaken fiscal policy.",
                "In Cameroon oil revenue, debt rules and project execution shape what fiscal policy can do."),
        ],
    ),
    # ================================================================ 12. Taxation
    lesson(
        module=M3, topic="Taxation",
        title="Taxation: principles, progressivity, incidence and the Laffer curve",
        slug="ecu1-taxation",
        minutes=25,
        summary="Canons of taxation, average and marginal tax rates, progressive, proportional and regressive taxes, formal and effective incidence and how elasticities share a tax, the Laffer curve, and the effects of higher income tax.",
        objectives=[
            "Explain the canons of taxation and judge a tax against them",
            "Calculate average and marginal tax rates and classify taxes as progressive, proportional or regressive",
            "Explain and calculate the incidence of an indirect tax using elasticities",
            "Analyse the Laffer curve and the effects of higher income tax on consumption, distribution and prices",
        ],
        key_concepts=["Canons of taxation", "Direct and indirect taxes", "Average tax rate", "Marginal tax rate",
                      "Progressive, proportional, regressive", "Formal and effective incidence", "Laffer curve", "Tax base"],
        blocks=[
            H("Introduction"),
            T("The government of Cameroon raises revenue from many sources: taxes on incomes and company profits, VAT and excise duties on spending, customs duties on imports, and non-tax revenue such as oil royalties and fees. "
              "Taxes finance public services, but they also change incentives, prices and the distribution of income. At A Level you must judge taxes, measure their burden and say who really pays them. (Rates and bands below are teaching values; check the current Finance Law for actual rates.)"),
            D("A **tax** is a compulsory payment to the government for which no direct service is given in return. A **direct tax** is levied on income or wealth and paid by the person on whom it falls (income tax, company tax). An **indirect tax** is levied on spending and collected through sellers (VAT, excise duties, customs duties).", title="Definition"),
            H("Principles of a good tax"),
            KEY("Adam Smith's four canons, and later additions", "Smith set out the first four in The Wealth of Nations (1776).", cards=[
                ["Equity", "People should pay according to their ability to pay."],
                ["Certainty", "The taxpayer should know how much, when and how to pay."],
                ["Convenience", "Collected at a convenient time and in a convenient way."],
                ["Economy", "Cost of collection should be small compared with the revenue."],
                ["Efficiency", "Distort decisions to work, save and invest as little as possible."],
                ["Flexibility", "Easy to adjust as economic conditions change."]]),
            H("Average and marginal rates"),
            F(r"\text{ATR} = \frac{\text{total tax}}{\text{total income}} \qquad \text{MTR} = \frac{\Delta\, \text{tax}}{\Delta\, \text{income}}", title="Average and marginal tax rates"),
            D("A tax is **progressive** if the average rate rises as income rises (the MTR is above the ATR), **proportional** if the average rate is constant, and **regressive** if the average rate falls as income rises.", title="Definition"),
            EX("Worked example 1: a progressive income tax", intro="Teaching bands (not Cameroon's actual schedule): first 500 000 FCFA of annual taxable income at 10%, the next 1 000 000 at 20%, everything above 1 500 000 at 30%. Find the tax, ATR and MTR on an income of 2 000 000.", steps=[
                S("First band", math=r"0.10 \times 500\,000 = 50\,000"),
                S("Second band", math=r"0.20 \times 1\,000\,000 = 200\,000"),
                S("Top band", math=r"0.30 \times (2\,000\,000 - 1\,500\,000) = 150\,000"),
                S("Total tax and ATR", math=r"400\,000,\quad \text{ATR} = \frac{400\,000}{2\,000\,000} = 20\%"),
                S("MTR", text="The next franc earned is taxed at 30%. Since MTR > ATR, the tax is progressive."),
            ], check=r"50\,000 + 200\,000 + 150\,000 = 400\,000"),
            EX("Worked example 2: is a sales tax regressive?", intro="A 10% tax applies to all spending. A poor household earns 200 000 and spends 190 000; a rich household earns 2 000 000 and spends 1 200 000. Compare the tax as a share of income.", steps=[
                S("Poor household", math=r"0.10 \times 190\,000 = 19\,000 = 9.5\% \text{ of income}"),
                S("Rich household", math=r"0.10 \times 1\,200\,000 = 120\,000 = 6\% \text{ of income}"),
                S("Conclusion", text="The rich pay more francs but a smaller share of income, so a flat tax on spending is regressive relative to income. Exempting basic foods reduces this effect."),
            ]),
            H("Incidence: who really pays?"),
            D("The **formal incidence** of a tax is on the person legally responsible for paying it. The **effective (economic) incidence** is on whoever bears the burden in the end, through higher prices paid or lower prices received.", title="Definition"),
            IMG("alecu1-incidence.svg", alt="Supply and demand diagram. A specific tax shifts supply from S1 up to S2. Price to consumers rises from P0 to P1; price received by producers falls to P2. A blue rectangle between P1 and P0 is the consumers' share; a green rectangle between P0 and P2 is the producers' share.", caption="Figure 1. A specific tax raises the consumer price from P0 to P1 and lowers the producer price to P2. The two shaded areas are the shares of tax revenue paid by each group."),
            F(r"\text{Consumers' share} \approx \frac{\text{PES}}{\text{PES} + |\text{PED}|} \qquad \text{Producers' share} \approx \frac{|\text{PED}|}{\text{PES} + |\text{PED}|}", title="Sharing the tax (small changes, linear curves)"),
            EX("Worked example 3: tax on a beverage", intro="A specific tax of 100 FCFA per bottle is placed on a soft drink. Near equilibrium PED = -0.5 and PES = 1.5. How much of the tax do consumers pay?", steps=[
                S("Consumers' share", math=r"\frac{1.5}{1.5 + 0.5} = 0.75"),
                S("In francs", math=r"0.75 \times 100 = 75 \text{ FCFA}", text="The price to consumers rises by about 75 francs; producers receive about 25 francs less."),
                S("Lesson", text="The side of the market that is LESS elastic bears MORE of the tax. Taxes on goods with inelastic demand (fuel, beer, cigarettes) fall mostly on consumers."),
            ]),
            H("The Laffer curve"),
            IMG("alecu1-laffer.svg", alt="Laffer curve: tax revenue against tax rate from 0 to 100 percent. Revenue rises from zero, reaches a maximum at t star and falls back to zero at 100 percent.", caption="Figure 2. The Laffer curve: beyond Tm, higher rates reduce revenue."),
            T("The **Laffer curve**, popularised by the American economist Arthur Laffer, shows tax revenue against the tax rate. At 0% revenue is zero; at 100% nobody has a reason to earn taxable income, so revenue is again zero. Somewhere between, revenue is at a maximum (Tm). Above Tm, cutting rates raises revenue because people work more, evade less and move activity out of the informal sector. "
              "The idea is accepted; the position of Tm is disputed and probably differs between taxes and countries. In economies with large informal sectors, high rates may mainly push activity out of the tax net."),
            KEY("Effects of a rise in income tax (directional)", "A Paper 2 question has asked exactly this; analyse each variable separately.", cards=[
                ["Consumption", "Disposable income falls, so consumption falls (by MPC x the extra tax); saving may also fall."],
                ["Distribution of income", "If the rise is on higher bands (more progressive), post-tax income becomes more equal; a flat rise takes the same share from all."],
                ["General price level", "Lower demand reduces demand-pull pressure, so inflation tends to fall; but if workers push for higher wages to protect take-home pay, cost-push pressure can offset this."],
                ["Incentives", "High marginal rates may reduce work effort, encourage evasion and the shift to the informal sector (the Laffer argument)."]]),
            MISTAKE("Judging progressivity by the amount paid", "The rich pay more francs under almost any tax. A tax is progressive only if the PROPORTION of income paid rises with income."),
            MISTAKE("Assuming the seller pays an indirect tax", "The seller hands it to the government (formal incidence), but the burden is shared according to elasticities."),
            QUIZ("Under the teaching bands of Worked example 1, what is the tax on an income of 1 000 000?",
                 ["100 000", "150 000", "200 000", "300 000"], 1,
                 "50 000 on the first 500 000 plus 20% of the next 500 000 (100 000) = 150 000.",
                 hint="Tax each slice of income at its own rate.",
                 feedback=["This taxes the whole income at 10%.", "", "This taxes the whole income at 20%.", "This taxes the whole income at 30%."]),
            QUIZ("Demand for a good is perfectly inelastic. Who bears a specific tax on it?",
                 ["Producers entirely", "Consumers and producers equally", "Consumers entirely", "The government"], 2,
                 "With |PED| = 0, the consumers' share PES/(PES + 0) is 1: the price rises by the full tax.",
                 hint="The less elastic side pays more.",
                 feedback=["Producers bear all of it only if supply is perfectly inelastic or demand perfectly elastic.", "Equal shares need equal elasticities.", "", "The government receives the tax; it does not bear it."]),
            TIP("In 2023 the Board reported a popular Paper 2 question on the sources of government revenue in Cameroon and the effects of higher income tax on consumption, income distribution and the price level; many candidates wrote generally instead of analysing each named variable. Paper 1 tests ATR/MTR, incidence and the canons.", title="Exam link"),
            PQ("Using the teaching bands, find the ATR and MTR on an income of 1 200 000.",
               "Tax = 50 000 + 0.20 x 700 000 = 190 000. ATR = 190 000 / 1 200 000 = 15.8%. MTR = 20%."),
            PQ("A tax of 200 FCFA per litre is put on fuel. PED = -0.2 and PES = 0.8. Estimate the rise in the consumer price.",
               "Consumers' share = 0.8 / (0.8 + 0.2) = 0.8, so the price rises by about 0.8 x 200 = 160 FCFA."),
            PQ("Distinguish between formal and effective incidence of a tax.",
               "Formal incidence is on the person legally required to pay the tax to the authorities, whereas effective incidence is on whoever finally bears its burden through the prices they pay or receive, which depends on the elasticities of demand and supply."),
            PQ("Discuss whether Cameroon should rely more on direct taxes than on indirect taxes.",
               "Plan: for direct taxes: can be progressive, so they fit ability to pay (equity); stable yield from formal-sector wages and profits; automatic stabilisers. Against: narrow base because many work in the informal sector; evasion and high collection costs; may weaken incentives (Laffer). Indirect taxes: wide base, hard to evade at the border and at registered sellers, quick revenue; but often regressive and can raise prices. Conclude: a mix is needed; broaden the base of direct taxes gradually (registration, digital payment) while protecting the poor by exempting basic goods from indirect taxes."),
            SUM("Canons: equity, certainty, convenience, economy (Smith), plus efficiency and flexibility.",
                "ATR = tax / income; MTR = change in tax / change in income; progressive if ATR rises with income.",
                "Effective incidence depends on elasticities: consumers' share = PES / (PES + |PED|).",
                "The Laffer curve: above some rate, higher rates reduce revenue; where that is, is disputed.",
                "Higher income tax lowers consumption, may equalise incomes and eases demand-pull inflation, but may weaken incentives."),
        ],
    ),
    # ================================================================ 13. The budget
    lesson(
        module=M3, topic="The budget",
        title="The government budget: balanced, surplus and deficit budgets and the PSBR",
        slug="ecu1-government-budget",
        minutes=24,
        summary="The functions of the budget, balanced, surplus and deficit budgets, current and capital budgets, primary, cyclical and structural balances, how deficits are financed, and the public sector borrowing requirement.",
        objectives=[
            "Explain the functions of the budget and the meaning of balanced, surplus and deficit budgets",
            "Calculate overall and primary balances and express them as a percentage of GDP",
            "Distinguish cyclical from structural deficits and explain the PSBR",
            "Evaluate ways of financing a deficit and when a deficit is justified",
        ],
        key_concepts=["Budget", "Balanced budget", "Budget surplus", "Budget deficit", "Primary balance",
                      "Cyclical and structural deficit", "Current and capital budget", "PSBR", "Deficit financing"],
        blocks=[
            H("Introduction"),
            T("In Cameroon, the government's budget is presented each year as a **Finance Law** (loi de finances) prepared by the Ministry of Finance and voted by Parliament. It lists expected revenue and authorised spending. Whether the budget is in deficit or surplus, and how the gap is filled, is one of the most closely watched facts about any economy."),
            D("The **budget** is the government's plan of revenue and expenditure for a financial year. It is **balanced** when planned revenue equals planned expenditure, in **surplus** when revenue exceeds expenditure, and in **deficit** when expenditure exceeds revenue.", title="Definition"),
            KEY("What the budget is for", "Richard Musgrave's classification of the three functions of public finance is the standard one.", cards=[
                ["Allocation", "Provide public and merit goods (roads, defence, schools, health) that markets under-provide."],
                ["Distribution", "Change the distribution of income through progressive taxes, transfers and spending on the poor."],
                ["Stabilisation", "Influence aggregate demand to reduce unemployment and inflation (fiscal policy)."]]),
            H("Measuring the balance"),
            T("Spending is often split into a **current (recurrent) budget** (salaries, goods and services, transfers, interest) and a **capital (investment) budget** (roads, dams, buildings). A government may aim to cover current spending from revenue and borrow only for capital projects that raise future output, a 'golden rule' some countries follow."),
            F(r"\text{Overall balance} = \text{revenue} - \text{total expenditure} \qquad \text{Primary balance} = \text{overall balance} + \text{interest payments}", title="Overall and primary balance"),
            EX("Worked example 1: overall and primary balance", intro="A government's revenue is 5 000 (billion FCFA, invented). Total spending is 5 600, of which 300 is interest on debt. GDP is 25 000. Find the overall and primary balances and express them as a percentage of GDP.", steps=[
                S("Overall balance", math=r"5\,000 - 5\,600 = -600", text="A deficit of 600."),
                S("Primary balance", math=r"-600 + 300 = -300", text="Excluding interest, the government still spends 300 more than it collects."),
                S("As a share of GDP", math=r"\frac{600}{25\,000} = 2.4\%,\quad \frac{300}{25\,000} = 1.2\%"),
                S("Why the primary balance matters", text="It shows whether current policy, apart from the burden of past debt, is adding to debt. A primary surplus is needed to reduce debt when interest is high."),
            ]),
            H("Cyclical and structural deficits"),
            D("The **cyclical deficit** is the part of the deficit caused by the trade cycle: in a recession, tax revenue falls and some spending rises automatically. The **structural deficit** is the part that would remain even if the economy were at its normal (trend) level of output.", title="Definition"),
            EX("Worked example 2: separating the two", intro="The actual deficit is 600. Economists estimate that, with output at trend, revenue would be 200 higher. Find the structural and cyclical deficits.", steps=[
                S("Cyclical deficit", math=r"200"),
                S("Structural deficit", math=r"600 - 200 = 400"),
                S("Meaning", text="A recovery would remove only 200; the other 400 needs a policy change (more revenue or less spending)."),
            ]),
            H("Financing a deficit and the PSBR"),
            D("The **public sector borrowing requirement (PSBR)** is the total amount the whole public sector (central government, local authorities and public enterprises) must borrow in a year to cover the gap between its spending and its revenue. Some countries now call it the public sector net cash requirement (check your textbook).", title="Definition"),
            EX("Worked example 3: the PSBR and its financing", intro="Central government deficit 600, local councils' deficit 40, public enterprises' deficit 60. The government finances its share by issuing domestic securities (250), external loans (300) and drawing on its bank deposits (50). Find the PSBR and check the financing of the central government deficit.", steps=[
                S("PSBR", math=r"600 + 40 + 60 = 700"),
                S("Central government financing", math=r"250 + 300 + 50 = 600", text="It matches the central government deficit."),
            ]),
            KEY("Ways to finance a deficit, and their effects", "", cards=[
                ["Domestic borrowing (bonds, Treasury bills)", "Uses domestic savings; may raise interest rates and crowd out private credit. In CEMAC, governments issue securities on the regional market (check current arrangements)."],
                ["External borrowing", "Brings in foreign exchange; creates future repayment in foreign currency and exchange risk."],
                ["Central bank financing", "Creating money; inflationary (quantity theory). Limited in CEMAC under BEAC's rules (check current rules)."],
                ["Running down deposits or selling assets", "Possible only once; privatisation receipts are a one-off."],
                ["Arrears", "Not paying suppliers on time; damages firms and is an unhealthy form of financing."]]),
            KEY("When is a deficit justified?", "Evaluation for essays.", cards=[
                ["Yes", "In a recession (Keynesian argument: close the deflationary gap); to finance investment with high future returns (roads, energy, education)."],
                ["Caution", "When the economy is near full capacity (inflation, crowding out); when debt is already high; when spending is current consumption, not investment."],
                ["Rules", "CEMAC's multilateral surveillance includes budget-balance and debt criteria (check the current figures); IMF-supported programmes also set targets."]]),
            MISTAKE("Confusing the deficit with the debt", "The deficit is a FLOW in one year; the national debt is the STOCK of past borrowing not yet repaid. Each deficit adds to the debt."),
            MISTAKE("Assuming a deficit always means expansionary policy", "Part may be cyclical, caused automatically by a recession. Look at the structural balance to judge the stance of policy."),
            QUIZ("Revenue is 3 200, total spending 3 500 and interest payments 250. What is the primary balance?",
                 ["-300", "-50", "+250", "-550"], 1,
                 "Overall balance = -300; adding back interest of 250 gives a primary deficit of 50.",
                 hint="Primary balance = overall balance + interest.",
                 feedback=["That is the overall balance, including interest.", "", "This ignores the overall deficit.", "This subtracts interest instead of adding it back."]),
            QUIZ("The deficit rises in a recession although tax rates and spending plans are unchanged. This increase is",
                 ["a structural deficit", "a cyclical deficit", "the PSBR of public enterprises", "a balanced budget"], 1,
                 "It comes from the cycle: revenue falls and some spending rises automatically.",
                 hint="Was there a policy change?",
                 feedback=["A structural deficit would remain at trend output.", "", "The PSBR covers the whole public sector; the question is about the cause.", "A balanced budget has no deficit."]),
            TIP("Paper 1 tests definitions and simple balance calculations. Paper 2 essays may ask you to explain budget types and evaluate deficit financing; Paper 3 may give a budget table to interpret. Always say whether a figure is a flow (deficit) or a stock (debt).", title="Exam link"),
            PQ("Revenue is 4 400 and spending 4 900, of which 350 is interest. GDP is 20 000. Find the overall and primary balances as a percentage of GDP.",
               "Overall = -500, which is 2.5% of GDP. Primary = -500 + 350 = -150, which is 0.75% of GDP."),
            PQ("Distinguish between a cyclical and a structural deficit.",
               "A cyclical deficit is caused by the trade cycle (revenue falls and benefits rise in a recession) and disappears when output returns to trend, whereas a structural deficit would remain even at trend output and can only be removed by policy changes."),
            PQ("State three ways a government can finance a budget deficit and one disadvantage of each.",
               "Domestic borrowing (may crowd out private investment); external borrowing (foreign-currency repayment and exchange risk); central bank financing (inflationary, and restricted in CEMAC); running down deposits or selling assets (one-off)."),
            PQ("Discuss whether a government in a developing country should always aim for a balanced budget.",
               "Plan: for balance: avoids debt build-up, interest burden and crowding out; signals discipline; supports the fixed exchange rate and reserves. Against: in a recession a balanced-budget rule forces pro-cyclical cuts; borrowing for high-return investment (infrastructure, education) can pay for itself through growth; a cyclical deficit is natural. Conclude: aim for balance over the cycle and on the current budget, while allowing well-managed borrowing for productive investment, within debt limits."),
            SUM("The budget allocates resources, redistributes income and stabilises the economy.",
                "Balanced, surplus and deficit budgets compare revenue with spending; the primary balance excludes interest.",
                "Cyclical deficits come from the trade cycle; structural deficits remain at trend output.",
                "The PSBR is the whole public sector's borrowing need; deficits are financed by domestic or external borrowing, money creation or asset sales.",
                "A deficit is easier to justify in a recession or for productive investment than when the economy is at full capacity."),
        ],
    ),
    # ================================================================ 14. The national debt
    lesson(
        module=M3, topic="The national debt",
        title="The national debt: burden, sustainability and management",
        slug="ecu1-national-debt",
        minutes=25,
        summary="Internal and external debt, measures such as debt-to-GDP and debt service ratios, the burden of debt, how interest rates, growth and the primary balance drive the debt ratio, and ways of managing and reducing debt, including debt relief.",
        objectives=[
            "Define the national debt and distinguish internal from external debt",
            "Calculate debt-to-GDP and debt service ratios and use the debt dynamics equation",
            "Explain the burdens of a national debt and when debt is sustainable",
            "Evaluate methods of managing and reducing the national debt",
        ],
        key_concepts=["National debt", "Internal and external debt", "Debt-to-GDP ratio", "Debt service ratio",
                      "Debt sustainability", "Interest-growth differential", "Debt rescheduling", "Debt relief (HIPC)"],
        blocks=[
            H("Introduction"),
            T("When a government runs deficits year after year, it borrows, and the borrowing adds up. In the 1980s and 1990s many African countries, Cameroon among them, built up debts they could not service. Cameroon reached the completion point of the Heavily Indebted Poor Countries (HIPC) initiative in 2006 and received large debt relief. "
              "Since then debt has risen again in many countries. Understanding what makes debt sustainable is now central to discussions of public finance."),
            D("The **national debt** (public debt) is the total outstanding stock of borrowing by the government that has not yet been repaid. It is a STOCK built up by past deficits (FLOWS). **Internal (domestic) debt** is owed to lenders inside the country; **external debt** is owed to foreign lenders (other governments, international institutions such as the IMF and World Bank, banks and bondholders), usually in foreign currency.", title="Definition"),
            H("Measuring the debt"),
            F(r"\text{Debt ratio} = \frac{\text{debt}}{\text{GDP}} \times 100 \qquad \text{Debt service ratio} = \frac{\text{interest} + \text{principal repaid on external debt}}{\text{export earnings}} \times 100", title="Two key ratios"),
            EX("Worked example 1: the ratios", intro="A government owes 9 000 (billion FCFA, invented); GDP is 25 000. External debt service this year is 300 and export earnings are 2 000. Find the debt ratio and the debt service ratio.", steps=[
                S("Debt ratio", math=r"\frac{9\,000}{25\,000} \times 100 = 36\%"),
                S("Debt service ratio", math=r"\frac{300}{2\,000} \times 100 = 15\%", text="Fifteen francs of every hundred earned from exports go to servicing external debt, leaving less to pay for imports."),
            ]),
            T("Absolute amounts mean little: a debt is heavy or light compared with the economy's ability to pay, shown by GDP, government revenue or exports. CEMAC's convergence criteria include a ceiling on public debt as a share of GDP (often quoted as 70%; check the current rules)."),
            H("Debt dynamics"),
            T("What happens to the debt ratio next year depends on three things: the interest rate paid on the debt (r), the growth rate of nominal GDP (g), and the primary balance (pb, as a share of GDP; a primary deficit adds to debt)."),
            F(r"d_{t+1} = d_t \times \frac{1 + r}{1 + g} - pb_{t+1}", title="Debt dynamics (d and pb as % of GDP)"),
            EX("Worked example 2: growth outpaces interest", intro="The debt ratio is 40%. The average interest rate on the debt is 5%, nominal GDP grows by 7%, and the government runs a primary deficit of 1% of GDP (pb = -1). Find next year's debt ratio.", steps=[
                S("Effect of interest and growth", math=r"40 \times \frac{1.05}{1.07} = 39.25"),
                S("Add the primary deficit", math=r"39.25 + 1 = 40.25\%"),
                S("Meaning", text="Because growth exceeds the interest rate, the economy 'grows out of' much of the debt; the ratio is almost stable despite a primary deficit."),
            ]),
            EX("Worked example 3: interest outpaces growth", intro="The debt ratio is 60%, r = 8%, g = 3%, and the government runs a primary SURPLUS of 1% of GDP. Find next year's ratio, and the primary surplus needed to keep the ratio at 60%.", steps=[
                S("Next year's ratio", math=r"60 \times \frac{1.08}{1.03} - 1 = 61.91\%", text="The ratio still rises, even with a primary surplus."),
                S("Surplus needed to stabilise", math=r"pb = d \times \frac{r - g}{1 + g} = 60 \times \frac{0.05}{1.03} = 2.91\%"),
                S("Lesson", text="When interest exceeds growth, a high debt can snowball; a government must run a sizeable primary surplus to stop it."),
            ], check=r"60 \times \frac{1.08}{1.03} - 2.91 = 60.00"),
            H("The burden of the debt"),
            KEY("Burdens and costs", "", cards=[
                ["Interest payments", "Take a growing share of revenue, crowding out spending on schools, health and roads."],
                ["External debt", "Must be serviced in foreign currency from export earnings; a real transfer of resources abroad; exposure to exchange rate and commodity price shocks."],
                ["Internal debt", "Partly 'owed to ourselves', but interest transfers income from taxpayers to bondholders (often richer), and borrowing may crowd out private investment."],
                ["Future generations", "If borrowing financed consumption rather than productive investment, future taxpayers pay without receiving the benefits."],
                ["Confidence", "High debt can raise borrowing costs and risk a debt crisis, forcing sudden cuts."]]),
            T("**Is debt always bad?** No. Borrowing for investment that raises future output (power stations, roads, ports, education) can pay for itself if the return exceeds the interest cost. The questions are what the money was used for, on what terms (interest, maturity, currency) it was borrowed, and whether growth exceeds the interest rate."),
            H("Managing and reducing debt"),
            KEY("Methods", "", cards=[
                ["Primary surpluses", "Raise revenue or cut spending; painful but direct."],
                ["Faster growth", "Raises the denominator (GDP) and revenue; supply-side reforms and good investment."],
                ["Inflation", "Reduces the real value of domestic-currency debt, but harms savers and is limited in CEMAC; it does not reduce foreign-currency debt."],
                ["Better terms", "Refinancing at lower interest, longer maturities, borrowing in local currency, concessional loans."],
                ["Rescheduling and relief", "Agreements with creditors (for example in the Paris Club) to delay or cancel payments; HIPC and the Multilateral Debt Relief Initiative cancelled much debt of eligible countries."],
                ["Asset sales and sinking funds", "Privatisation receipts or a fund set aside each year to repay debt."]]),
            MISTAKE("Using deficit and debt as the same thing", "A deficit adds to the debt in one year; the debt is the total stock. A falling deficit still means a rising debt as long as there is a deficit."),
            MISTAKE("Judging debt by its size in francs", "Always compare debt with GDP, revenue or exports, and look at interest rates and growth."),
            QUIZ("The debt ratio is 50%, r = 6%, g = 4% and the primary balance is a deficit of 2% of GDP. What is next year's debt ratio, approximately?",
                 ["49.0%", "51.0%", "53.0%", "56.0%"], 2,
                 "50 x 1.06 / 1.04 = 50.96, plus the 2-point primary deficit = 52.96%, about 53%.",
                 hint="Apply the debt dynamics equation; a primary deficit ADDS to the ratio.",
                 feedback=["This subtracts the primary deficit instead of adding it.", "This forgets the primary deficit.", "", "This adds the interest rate as if it were added directly."]),
            QUIZ("Why is external debt often a heavier burden than internal debt of the same size?",
                 ["It must be serviced in foreign currency earned from exports", "It never has to be repaid", "Its interest stays inside the country", "It is always interest-free"], 0,
                 "Servicing it takes resources out of the country and depends on export earnings and the exchange rate.",
                 hint="Where does the money to pay foreign creditors come from?",
                 feedback=["", "External loans have to be repaid unless relief is granted.", "Interest on external debt goes abroad.", "Some concessional loans have low rates, but not all external debt is interest-free."]),
            TIP("Paper 2 may ask you to discuss the burden of the national debt or ways to manage it; Paper 3 may give debt and GDP data to interpret. Calculate ratios, then explain them using interest, growth and the primary balance.", title="Exam link"),
            PQ("A government's debt is 12 000 and GDP is 40 000. External debt service is 450 and exports are 3 000. Find the debt ratio and the debt service ratio.",
               "Debt ratio = 12 000 / 40 000 = 30%. Debt service ratio = 450 / 3 000 = 15%."),
            PQ("The debt ratio is 45%, r = 4%, g = 6%, and there is a primary surplus of 1.5% of GDP. Find next year's ratio.",
               "45 x 1.04 / 1.06 - 1.5 = 44.15 - 1.5 = 42.65%. The ratio falls: growth above interest plus a primary surplus."),
            PQ("Distinguish between internal and external debt and explain one burden of each.",
               "Internal debt is owed to residents, usually in local currency, whereas external debt is owed to foreign lenders, usually in foreign currency. Internal: interest transfers income from taxpayers to bondholders and borrowing can crowd out private investment. External: servicing it takes foreign exchange from export earnings and transfers real resources abroad."),
            PQ("Evaluate the methods a government such as Cameroon's could use to reduce the burden of its national debt.",
               "Plan: primary surpluses (direct but may slow growth and cut services); faster growth through investment and reforms (best long-run route, but uncertain); better borrowing terms (concessional loans, longer maturities, local currency) to reduce cost and risk; rescheduling or relief (Cameroon benefited from HIPC in 2006; future relief is not guaranteed and carries conditions); inflation (limited by the CEMAC framework and does not reduce foreign-currency debt); asset sales (one-off). Conclude: combine moderate primary surpluses with growth-enhancing investment and prudent borrowing; the ratio, not the absolute amount, should be the target."),
            SUM("The national debt is the stock of past government borrowing; internal debt is owed at home, external debt abroad.",
                "Key measures: debt-to-GDP ratio and debt service ratio (debt service / exports).",
                "d(next) = d x (1 + r)/(1 + g) - pb: debt snowballs when r > g unless there is a primary surplus.",
                "Burdens: interest crowding out spending, foreign-exchange drain, crowding out, intergenerational costs.",
                "Manage debt through primary surpluses, growth, better terms, rescheduling or relief; inflation is limited and harmful."),
        ],
    ),
]
